INSERT INTO `artists` VALUES (1,'鄧麗君','鄧麗君，本名鄧麗筠，臺灣女歌手、演員及慈善家。她是20世紀後期華語流行音樂極具代表性的人物，也是當代華語音樂的先驅之一。時至今日，鄧麗君仍被視為全球華人地區流行文化的代表人物之一。','https://zh.wikipedia.org/wiki/%E9%84%A7%E9%BA%97%E5%90%9B','2026-04-06 22:15:51','2026-04-06 14:11:56','2026-04-06 14:15:51'),(2,'MIKA NAKASHIMA','中島美嘉 是日本歌手與演員，鹿兒島縣日置市伊集院町出身，所屬經紀公司為True Project，所屬唱片公司則為日本索尼音樂娛樂。','https://zh.wikipedia.org/wiki/%E4%B8%AD%E5%B3%B6%E7%BE%8E%E5%98%89','2026-04-06 22:15:53','2026-04-06 14:11:56','2026-04-06 14:15:53'),(3,'沈文程','沈文程（1954年6月6日—），本名周沈文程，臺灣男演員、主持人及歌手，是金曲獎和金鐘獎的得主，畢業於空軍機械學校（今空軍航空技術學院）。','https://zh.wikipedia.org/wiki/%E6%B2%88%E6%96%87%E7%A8%8B','2026-04-06 22:15:54','2026-04-06 14:11:56','2026-04-06 14:15:54'),(4,'木與銅的對話-林子葇與黃芝庭聯合','木與銅的對話-林子葇與黃芝庭聯合 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(5,'東光國小管樂團2026年度','《島嶼天光 Island\'s Sunrise》簡稱《島嶼天光》，是2014年時由臺灣搖滾樂團滅火器樂團與國立臺北藝術大學共同為太陽花學運創作的台語歌曲，天光是指天亮。其中由臺北藝術大學團隊吳達坤、陳敬元等人企劃，再邀請滅火器樂團創作歌曲後結合企劃團隊製作「紀實版」與動畫系同學製作「動畫版」兩版本MV，之後改編管弦樂版本。滅火器樂團還無償提供〈晚安臺灣〉和〈島嶼天光〉兩首歌的版權給支持太陽花學運的民眾非商業行為使用，〈島嶼天光〉也被廣泛視為太陽花學運的重要歌曲之一，因而遭到中国大陆官方封杀。這首歌在2014年12月30日由台灣索尼音樂娛樂發行單曲，並於翌年第26屆金曲獎獲得最佳年度歌曲殊榮。','https://zh.wikipedia.org/wiki/%E5%B3%B6%E5%B6%BC%E5%A4%A9%E5%85%89','2026-04-06 22:16:03','2026-04-06 14:11:56','2026-04-06 14:16:03'),(6,'巧虎','《可愛巧虎島》 是由瀨戶內電視台監製、東京電視網首播的日本電視動畫，主要以幼兒為對象。','https://zh.wikipedia.org/wiki/%E5%8F%AF%E6%84%9B%E5%B7%A7%E8%99%8E%E5%B3%B6','2026-04-06 22:16:05','2026-04-06 14:11:56','2026-04-06 14:16:05'),(7,'寶吉祥歌之饗宴15-一路上的愛呀 陳怡婷','寶吉祥歌之饗宴15-一路上的愛呀 陳怡婷 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(8,'學年度楠梓國小管樂班成果','高雄市立中山高級中學，簡稱中山高中或中山高。是一所位於台灣高雄市楠梓區的市立高級中學，創立於1990年7月1日，鄰近高雄大學及左營軍港，四周有大小崗山、觀音山、半屏山、壽山。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AB%8B%E4%B8%AD%E5%B1%B1%E9%AB%98%E7%B4%9A%E4%B8%AD%E5%AD%B8','2026-04-06 22:16:13','2026-04-06 14:11:56','2026-04-06 14:16:13'),(9,'王建傑2026傑然不同','傑志體育會 是香港一間歷史悠久的體育會，成立於1931年，以其足球隊最為知名，是香港足球聯賽的傳統勁旅，為現時香港超級聯賽的班霸。','https://zh.wikipedia.org/wiki/%E5%82%91%E5%BF%97%E9%AB%94%E8%82%B2%E6%9C%83','2026-04-06 22:16:15','2026-04-06 14:11:56','2026-04-06 14:16:15'),(10,'龍千玉','江玉滿（1961年7月30日—），藝名龍千玉，前藝名江玉琴，台灣女歌手，出生於基隆市中正區。','https://zh.wikipedia.org/wiki/%E9%BE%8D%E5%8D%83%E7%8E%89','2026-04-06 22:16:17','2026-04-06 14:11:56','2026-04-06 14:16:17'),(11,'MISIA','米希亞 是日本女性歌手、作曲家，出生於長崎縣對馬市，所屬經紀公司為Rhythmedia，所屬唱片公司為日本索尼音乐旗下品牌Ariola Japan。生物多样性公约签署国第10次会议形象大使。','https://zh.wikipedia.org/wiki/%E7%B1%B3%E5%B8%8C%E4%BA%9E','2026-04-06 22:16:19','2026-04-06 14:11:56','2026-04-06 14:16:19'),(12,'洪榮宏 舊情綿綿','洪榮宏（1963年3月19日—）是臺灣男歌手、主持人，為臺語歌手洪一峰的長子。2010年7月開始擔任臺灣優質生命協會理事長一職。是三金（金馬、金曲、金鐘）入圍者。','https://zh.wikipedia.org/wiki/%E6%B4%AA%E6%A6%AE%E5%AE%8F','2026-04-06 22:16:21','2026-04-06 14:11:56','2026-04-06 14:16:21'),(13,'自由之地 楊烈世界','楊烈（1952年10月13日—），原名楊松福，出生於台灣台北市，畢業於台北市立體育學院（早期為體育專校）以及泰北高中（早期為泰北中學）。台灣男藝人、同時也是民主進步黨黨員。','https://zh.wikipedia.org/wiki/%E6%A5%8A%E7%83%88','2026-04-06 22:16:23','2026-04-06 14:11:56','2026-04-06 14:16:23'),(14,'傻豆騎士系列-','《假面騎士EX-AID》，是日本東映公司在2016年推出的《假面騎士系列》的第18部平成系列特攝作品。於2016年（平成28年）10月2日至2017年（平成29年）8月27日，每週日早上08:00-08:30於朝日電視台播出，共45集。本作也是假面騎士系列誕生45週年紀念作品，口號是「Game Start!」、「No Continue來改變命運吧！！」。','https://zh.wikipedia.org/wiki/%E5%81%87%E9%9D%A2%E9%A8%8E%E5%A3%ABEX-AID','2026-04-06 22:16:25','2026-04-06 14:11:56','2026-04-06 14:16:25'),(15,'Whee','《WHEE》是南韓女歌手MAMAMOO成員輝人的第二張個人迷你專輯，於2022年1月16日由THE L1VE發行，主打歌為〈오묘해 〉。','https://zh.wikipedia.org/wiki/WHEE','2026-04-06 22:16:27','2026-04-06 14:11:56','2026-04-06 14:16:27'),(16,'The Itchyworms','The Itchyworms is a Filipino rock band. The band is composed of Jugs Jugueta on Vocals and Guitar, Jazz Nicolas on Vocals and Drums, Kelvin Yu on Bass and Vocals, Chino Singson on Lead Guitar, Weckl Mercado on Guitar and Vocals and Michael Vargas on Vocals, Keyboards, Violin, Acoustic Guitar, and Percussion. The group…','https://en.wikipedia.org/wiki/The_Itchyworms','2026-04-06 22:16:30','2026-04-06 14:11:56','2026-04-06 14:16:30'),(17,'False Apart','維基百科 是维基媒体基金会运营的一个多语言的線上百科全書，并以创建和维护作为开放式协同合作项目，特点是自由內容、自由编辑、自由版权。目前是全球網絡上最大且最受大眾歡迎的参考工具书，名列全球二十大最受歡迎的網站，其在搜尋引擎中排名亦較為靠前。維基百科目前由非營利組織維基媒體基金會負責營運。Wikipedia是混成詞，分别取自於網站核心技術「Wiki」以及英文中百科全書之意的「encyclopedia」。截至2023年11月，所有語言的维基百科有超过6200万篇條目，每月超过1400万次编辑（平均每秒约5.2次编辑），每月有超過20億個獨立設備訪問各個語言的維基百科網站。大约26%的流量来自美国，其次是日本（5.9%）、英国（5.4%…','https://zh.wikipedia.org/wiki/%E7%BB%B4%E5%9F%BA%E7%99%BE%E7%A7%91','2026-04-06 22:16:32','2026-04-06 14:11:56','2026-04-06 14:16:32'),(18,'EmptyORio','Empty ORio，是滅火器樂團吉他手鄭宇辰個人首張全創作專輯，數位發行是2018年4月30日，2018年5月11日正式發行。','https://zh.wikipedia.org/wiki/Empty_ORio_(%E9%84%AD%E5%AE%87%E8%BE%B0%E5%B0%88%E8%BC%AF)','2026-04-06 22:16:34','2026-04-06 14:11:56','2026-04-06 14:16:34'),(19,'噬星 Galaxy Destruction Inc. (TW)','Zangief（桑吉爾夫），是一個來自臺灣台北的金屬樂團，成立於2012年。樂團曲風早期為金屬蕊，後期加入後硬核、前衛金屬、Djent。','https://zh.wikipedia.org/wiki/%E6%A1%91%E5%90%89%E7%88%BE%E5%A4%AB','2026-04-06 22:16:37','2026-04-06 14:11:56','2026-04-06 14:16:37'),(20,'暴君 Bloody Tyrant (TW)','Zangief（桑吉爾夫），是一個來自臺灣台北的金屬樂團，成立於2012年。樂團曲風早期為金屬蕊，後期加入後硬核、前衛金屬、Djent。','https://zh.wikipedia.org/wiki/%E6%A1%91%E5%90%89%E7%88%BE%E5%A4%AB','2026-04-06 22:16:38','2026-04-06 14:11:56','2026-04-06 14:16:38'),(21,'鏡裂Ecstasia  w','鏡裂Ecstasia w 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(22,'曖昧な寶石','魔法少女小圓角色列表，是日本電視動畫《魔法少女小圓》 及其續作《劇場版 魔法少女小圓［新篇］叛逆的物語》，加上外傳漫畫作品——《魔法少女小織》、《魔法少女和美 〜The innocent malice〜》、《魔法少女貞德 The Legend of \"Jeanne d\'Arc\"》、《魔法少女鈴音》，遊戲——《魔法紀錄 魔法少女小圓外傳》所有登場人物的介紹。','https://zh.wikipedia.org/wiki/%E9%AD%94%E6%B3%95%E5%B0%91%E5%A5%B3%E5%B0%8F%E5%9C%93%E8%A7%92%E8%89%B2%E5%88%97%E8%A1%A8','2026-04-06 22:16:47','2026-04-06 14:11:56','2026-04-06 14:16:47'),(23,'琉璃花','《花琉璃轶闻》，原名《造作时光》，改编自作家月下蝶影创作的同名小说《造作时光》，中国大陆古装网络剧。该剧由徐正溪、孟子义主演，于2021年拍摄。2022年1月11日順利殺青，2023年3月15日在騰訊視頻播出。','https://zh.wikipedia.org/wiki/%E8%8A%B1%E7%90%89%E7%92%83%E8%BD%B6%E9%97%BB','2026-04-06 22:16:49','2026-04-06 14:11:56','2026-04-06 14:16:49'),(24,'Mai舞','門脇舞以，日本女性聲優。Kaleidoscope所屬。東京都出身。血型O型。本名及舊藝名為門脇舞。愛稱和自稱是舞太（まいた）。','https://zh.wikipedia.org/wiki/%E9%96%80%E8%84%87%E8%88%9E%E4%BB%A5','2026-04-06 22:16:51','2026-04-06 14:11:56','2026-04-06 14:16:51'),(25,'Ruka Banana','搖滾台中 首屆由搖滾開跑音樂社於 2007 年在豐原體育場舉辦，原名為「搖滾台中無限自由音樂節」，2008 年起與臺中市政府合作，自 2009 年開始由市府接手為每年舉辦之音樂節。期待能讓民眾能夠體現臺中市音樂文化質地的美好，同時運用臺中的地理位置優勢、豐沛的文化元素、優秀的音樂人才，持續將「搖滾台中」打造成為臺灣流行音樂不可錯過的盛宴。','https://zh.wikipedia.org/wiki/%E6%90%96%E6%BB%BE%E8%87%BA%E4%B8%AD','2026-04-06 22:16:54','2026-04-06 14:11:56','2026-04-06 14:16:54'),(26,'Ghost In The Sky Tour @Revolver','本电子游戏列表列举了索尼PlayStation 2的电子游戏。','https://zh.wikipedia.org/wiki/PlayStation_2%E6%B8%B8%E6%88%8F%E5%88%97%E8%A1%A8','2026-04-06 22:16:57','2026-04-06 14:11:56','2026-04-06 14:16:57'),(27,'我是機車少女 I\'m difficult','我是機車少女 I\'m difficult 為本資料庫收錄之演出藝人。近期相關報導包含：《2025 Simple Life簡單生活節》11/29、30華山文創園區登場！20週年全陣容、場域圖、時間表公開。','https://news.google.com/rss/articles/CBMiS0FVX3lxTE1uOXNCR3ppb1ZCaFQ4ajRIQklKTlI3c2tWX0o1Z0V5TXhRcWNtV0FrN1k4NWs5M0ZxQUlsdDRYWkx4MnJreEV2VWJPMA?oc=5','2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(28,'野巢 Nosu','鴻巢站 是屬於東日本旅客鐵道（JR東日本）高崎線的鐵路車站，位於埼玉縣鴻巢市本町。','https://zh.wikipedia.org/wiki/%E9%B4%BB%E5%B7%A2%E7%AB%99','2026-04-06 22:17:08','2026-04-06 14:11:56','2026-04-06 14:17:08'),(29,'粗大Band','大港開唱 為臺灣指標性音樂祭，通常於每年三月在高雄舉辦，活動包含國內外一百組以上的表演者，也是以南台灣演出陣容為主之獨立音樂節。','https://zh.wikipedia.org/wiki/%E5%A4%A7%E6%B8%AF%E9%96%8B%E5%94%B1','2026-04-06 22:17:10','2026-04-06 14:11:56','2026-04-06 14:17:10'),(30,'後站人','《鏈鋸人》 是由日本漫畫家藤本樹所創作的黑暗奇幻少年漫畫，該作於2018年12月3日發售的《週刊少年Jump》2019年第1號開始連載，這也是藤本樹首度在該雜誌連載的作品。故事主要描述一名斬殺惡魔維生的少年——淀治，經歷意外後重生並獲得了「鏈鋸惡魔」的力量，從此加入公安部門與各式惡魔交戰。','https://zh.wikipedia.org/wiki/%E9%8F%88%E9%8B%B8%E4%BA%BA','2026-04-06 22:17:12','2026-04-06 14:11:56','2026-04-06 14:17:12'),(31,'我萱 聯合發片','任家萱（1981年10月31日—），藝名Selina，臺灣女歌手、演員、主持人，為女子演唱團體S.H.E組合成員。出生於台灣台北市，因2000年參加《宇宙2000實力美少女爭霸戰》獲得冠軍，並於同年與宇宙唱片（華研唱片前身）簽約培訓後，在2001年9月11日以S.H.E成員身分發行團體首張專輯《女生宿舍》進入演藝圈。其妹妹為演員任容萱。2010年10月22日在上海拍攝電視劇時發生爆破意外事件，使個人與團體演藝事業暫停。2011年1月19日，舉辦記者會並正式出院。2011年12月推出首張個人迷你專輯《重作一個夢》。2015年1月9日，發行首張個人專輯《3.1415》。2022年4月29日，發行第二張個人專輯《往美的路我要自己作主》。','https://zh.wikipedia.org/wiki/%E4%BB%BB%E5%AE%B6%E8%90%B1','2026-04-06 22:17:14','2026-04-06 14:11:56','2026-04-06 14:17:14'),(32,'Matzka','Matzka，漢名宋唯農，臺灣創作歌手、詞曲作家與音樂製作人，臺東縣金峰鄉排灣族人，MATZKA樂團主唱。其岳父是中華民國立法委員高金素梅前辦公室主任、現任助理張俊傑，2026年2月因案被收押，老婆則為嫌疑人，裁定五十萬元交保並限制出境。','https://zh.wikipedia.org/wiki/Matzka','2026-04-06 22:17:16','2026-04-06 14:11:56','2026-04-06 14:17:16'),(33,'SONNIE桑尼 2026 不插電','搖滾台中 首屆由搖滾開跑音樂社於 2007 年在豐原體育場舉辦，原名為「搖滾台中無限自由音樂節」，2008 年起與臺中市政府合作，自 2009 年開始由市府接手為每年舉辦之音樂節。期待能讓民眾能夠體現臺中市音樂文化質地的美好，同時運用臺中的地理位置優勢、豐沛的文化元素、優秀的音樂人才，持續將「搖滾台中」打造成為臺灣流行音樂不可錯過的盛宴。','https://zh.wikipedia.org/wiki/%E6%90%96%E6%BB%BE%E8%87%BA%E4%B8%AD','2026-04-06 22:17:18','2026-04-06 14:11:56','2026-04-06 14:17:18'),(34,'LANY','金志垣（yuán），藝名 LIZ，韓國女艺人，是女子組合IVE的Vocal，所屬經紀公司為STARSHIP娛樂。','https://zh.wikipedia.org/wiki/Liz_(IVE)','2026-04-06 22:17:20','2026-04-06 14:11:56','2026-04-06 14:17:20'),(36,'Post Malone','奧斯汀·理查德·波斯特，以其藝名巨星·馬龍 闻名，是一名美國歌手、演員、饒舌歌手、詞曲作家和音樂製作人。其作品融合了不同的流行种类，包括嘻哈、節奏藍調、流行、陷阱音樂和摇滚的音乐风格，内省的词曲创作，简洁的声线令马龙广受欢迎。马龙出生在纽约州的锡拉丘兹，在德克萨斯州的格雷普韦恩长大。他于2015年发布其首张单曲〈White Iverson〉出道，这首歌在《告示牌》百强单曲榜中排名第14，并获得了与聯眾唱片签订的唱片合约。他的藝名源自於饒舌產生器。','https://zh.wikipedia.org/wiki/%E6%B3%A2%E5%85%B9%C2%B7%E9%A9%AC%E9%BE%99','2026-04-06 22:17:24','2026-04-06 14:11:56','2026-04-06 14:17:24'),(38,'IVE','IVE，是韓國女子音樂團體，以朗朗上口的歌曲而闻名，並登上韓國富比士名人榜，成為達成最多Perfect all-kill的女子團體（共6首）。成員包括Gaeul、Yujin、Rei、Wonyoung、Liz和Leeseo，並由Yujin擔任隊長。2021年由STARSHIP娛樂推出。IVE以單曲專輯《ELEVEN》出道。','https://zh.wikipedia.org/wiki/IVE','2026-04-06 22:17:26','2026-04-06 14:11:56','2026-04-06 14:17:26'),(39,'Kodaline','Kodaline是一支来自爱尔兰首府都柏林的另类摇滚樂團。2007年3月，这支乐團的首支单曲《Give Me A Minute》在爱尔兰单曲榜成功登顶，创造了新的记录。此前历史上从未有独立发行的单曲成功登顶。 在2012年9月，柯達線发行了他们的首张迷你专辑《The Kodaline - EP》。該EP中收录的歌曲《All I Want》大受好评，並于2011年被BBC Radio 1收录在「DJ Fearne Cotton\'s Record of the Week」中，又出现在美剧《实习医生格蕾》第九季第二集“Remember The Time”中，同时更成为了《2012年度谷歌时代精神》 短片的背景音乐。2012年9月9日，B…','https://zh.wikipedia.org/wiki/%E6%9F%AF%E9%81%94%E7%B7%9A%E6%A8%82%E5%9C%98','2026-04-06 22:17:29','2026-04-06 14:11:56','2026-04-06 14:17:29'),(41,'公館青少年','王品澔（1999年10月11日—）是台灣男演員、模特兒、歌手，客家人。','https://zh.wikipedia.org/wiki/%E7%8E%8B%E5%93%81%E6%BE%94','2026-04-06 22:17:31','2026-04-06 14:11:56','2026-04-06 14:17:31'),(42,'Michael Learns to Rock','搖滾麥克 是成立于1988年的丹麦男子樂團，风格为軟式搖滾和流行搖滾，歌曲以英语為主。乐队目前的成员有Jascha Richter、Mikkel Lentz和Kåre Wanscher。乐队创始成员之一的Søren Madsen在2000年退出。','https://zh.wikipedia.org/wiki/%E8%BF%88%E5%85%8B%E5%AD%A6%E6%91%87%E6%BB%9A','2026-04-06 22:17:34','2026-04-06 14:11:56','2026-04-06 14:17:34'),(43,'ITZY','ITZY，是韓國JYP娛樂推出的女子音樂團體。成員包括：隊長禮志、Lia、留眞、彩領及有娜。2019年2月12日發行單曲專輯《IT\'z Different》出道，主打歌〈DALLA DALLA〉在《人氣歌謠》、《Show! 音樂中心》和《M! Countdown》分別拿下冠軍，隨後拿到《人氣歌謠》第一次「三冠王」的榮譽。ITZY榮獲韓國知名「金唱片獎」的「最佳新人獎」和「最佳音源本賞」，成為首個於出道年同時獲頒此兩項大獎的團體。','https://zh.wikipedia.org/wiki/ITZY','2026-04-06 22:17:35','2026-04-06 14:11:56','2026-04-06 14:17:35'),(44,'龜梨和也','龜梨和也 出身於日本東京都江戶川區的歌手、演員、藝人、體育節目主播、電視、廣播節目主持人。小時候因親戚姊姊為他報名傑尼斯，他在不知情的情況之下，被父親帶到徵選現場，被錄取之後，成為日本偶像經紀公司傑尼斯事務所旗下的男子偶像團體「KAT-TUN」成員之一，代表色為粉紅色。','https://zh.wikipedia.org/wiki/%E9%BE%9C%E6%A2%A8%E5%92%8C%E4%B9%9F','2026-04-06 22:17:37','2026-04-06 14:11:56','2026-04-06 14:17:37'),(46,'TPE48','TPE48 是由日本詞曲作家秋元康擔任總製作人，台灣音樂製作人陳子鴻擔任顧問的臺灣大型女子偶像團體，為女子偶像團體AKB48在海外的姊妹團體之一，以臺北為基地展開活動。於2017年中開始籌備，2018年2月4日團員正式公開亮相；原預計2018年6月在樂壇出道，後來因營運公司發生財務危機，導致活動暂时停止。2018年7月30日，AKB48的營運公司AKS透過媒體宣布解除原營運公司有關TPE48的授權合約，除了接手經營並將團體改名為「AKB48 Team TP」之外，也在台灣成立「好言娛樂有限公司」做為營運單位，之後於同年8月26日首次以新團名正式公開亮相。2026年1月18日，團體宣布將更名回最初團名「TPE48」，於同年1月21日…','https://zh.wikipedia.org/wiki/TPE48','2026-04-06 22:17:40','2026-04-06 14:11:56','2026-04-06 14:17:40'),(47,'BUS','BUS，為泰國SONRAY MUSIC於2023年選秀節目《789 Survival》中選出的12人男子音樂團體。成員分別由Alan、Marckris、Khunpol、Heart、Jinwook、Thai、Nex、Phutatchai、Copper、AA、Jungt及Peemwasu所組成。組合中亦分為五人小分隊BUS5及七人小分隊BUS7。','https://zh.wikipedia.org/wiki/BUS','2026-04-06 22:17:42','2026-04-06 14:11:56','2026-04-06 14:17:42'),(49,'Anson Seabra','泡泡岛音乐与艺术节 是由创娱无界创办的的音乐节，首届于2023年在天津举办，吸引了超6万人到场。凭借其国际化的艺人阵容、创新的主题设置和多元化的艺术表演，迅速成为中国最具影响力的音乐节IP之一。','https://zh.wikipedia.org/wiki/%E6%B3%A1%E6%B3%A1%E5%B2%9B%E9%9F%B3%E4%B9%90%E4%B8%8E%E8%89%BA%E6%9C%AF%E8%8A%82','2026-04-06 22:17:44','2026-04-06 14:11:56','2026-04-06 14:17:44'),(52,'美秀集團','美秀集團 是台灣嘉義的獨立樂團，曲風特色是帶有復古台味的搖滾和民謠，樂團採用自製樂器進行演出。該樂團自2016年5月開始對外活動，目前成員由主唱狗柏、鍵盤手冠佑、鼓手鍾錡以及貝斯手婷文組成。 團名「美秀」取自狗柏、冠佑兩位母親的名字。','https://zh.wikipedia.org/wiki/%E7%BE%8E%E7%A7%80%E9%9B%86%E5%9C%98','2026-04-06 22:17:46','2026-04-06 14:11:56','2026-04-06 14:17:46'),(53,'WOODZ','曹承衍，藝名WOODZ，是韓國創作歌手與製作人。他成功地從偶像團體成員轉型為引領搖滾與R&B風潮的獨唱藝人。','https://zh.wikipedia.org/wiki/%E6%9B%B9%E6%89%BF%E8%A1%8D','2026-04-06 22:17:48','2026-04-06 14:11:56','2026-04-06 14:17:48'),(54,'告五人','告五人（Accusefive），台灣樂團，其2011年成立於宜蘭縣，2017年改組為三人團體發行首張EP，目前團員為男主唱兼吉他手潘雲安、女主唱犬青及鼓手兼團長林哲謙。在2024年以〈又到天黑〉榮獲第35屆金曲獎年度歌曲獎。','https://zh.wikipedia.org/wiki/%E5%91%8A%E4%BA%94%E4%BA%BA','2026-04-06 22:17:50','2026-04-06 14:11:56','2026-04-06 14:17:50'),(55,'ZUTOMAYO','永远是深夜有多好。 又称ZUTOMAYO，是源自日本的音樂團體。其作詞作曲均由擔任主唱的 ACAね（ACA-Ne）獨自或與他人合作完成。粉絲愛稱為「ずとまろ（ZUTOMARO）」','https://zh.wikipedia.org/wiki/%E6%B0%B8%E8%BF%9C%E6%98%AF%E6%B7%B1%E5%A4%9C%E6%9C%89%E5%A4%9A%E5%A5%BD%E3%80%82','2026-04-06 22:17:51','2026-04-06 14:11:56','2026-04-06 14:17:51'),(56,'Laufey','勒伊费·林冰·约恩斯多蒂尔OTF 是一位中冰混血创作歌手和多乐器演奏家。2020年代初期，她创作的融合了爵士风格的流行音乐大获成功，开始在乐坛展崭露头角。','https://zh.wikipedia.org/wiki/%E6%9E%97%E5%86%B0_(%E6%AD%8C%E6%89%8B)','2026-04-06 22:17:53','2026-04-06 14:11:56','2026-04-06 14:17:53'),(57,'羊駝小姐','Leo王，本名王之佑，是出身自臺灣高雄的華語流行音樂創作歌手。他是龐克搖滾樂團巨大的轟鳴的主唱，以及饒舌演唱組合夜貓組的成員。2019年，以第三張個人專輯《無病呻吟有情抒情》獲頒第30屆金曲獎最佳國語男歌手獎。','https://zh.wikipedia.org/wiki/Leo%E7%8E%8B','2026-04-06 22:17:55','2026-04-06 14:11:56','2026-04-06 14:17:55'),(59,'Tizzy Bac','Tizzy Bac（中文團名鐵之貝克），是台灣獨立樂團，成立於1999年，由陳惠婷（主唱兼鍵盤手）、許哲毓（貝斯手）、林前源（鼓手）三人組成。主要活動區域為北部，常在台北市各大表演場地演出。貝斯手許哲毓於2018年1月23日因癌症離世。','https://zh.wikipedia.org/wiki/Tizzy_Bac','2026-04-06 22:17:57','2026-04-06 14:11:56','2026-04-06 14:17:57'),(60,'ARKis','ARKis 是台灣踢帕娛樂旗下八人男子音樂組合，為選秀節目《原子少年2》人氣團，成員由Alex 、黃崇峻、Vin、鄭彫秦、禾雁凱、伍承慶、李東翰及李定所組成，2024年12月29日於原子少年2(Atom boyz2)畢業演唱會正式出道。','https://zh.wikipedia.org/wiki/ARKis','2026-04-06 22:17:59','2026-04-06 14:11:56','2026-04-06 14:17:59'),(61,'齊豫','齊豫，台灣女歌手，1980年代華語圈最为活跃的歌手之一，因其獨特的唱腔和出色的唱功，被誉为“天籟之音”。代表作有〈橄欖樹〉、〈夢田〉、〈歡顏〉、〈你是我所有的回憶〉等歌曲。曾於1998年以專輯《駱駝·飛鳥·魚》榮獲第9屆流行音樂金曲獎最佳國語女演唱人獎，也是弟弟齐秦和周华健加入乐坛的引路人。近年專注於修習佛法，並投入佛教音樂領域，於2021年榮獲第32屆傳統藝術金曲獎最佳宗教音樂專輯。','https://zh.wikipedia.org/wiki/%E9%BD%8A%E8%B1%AB','2026-04-06 22:18:01','2026-04-06 14:11:56','2026-04-06 14:18:01'),(62,'湯令山','湯令山，藝名Gareth. T，香港創作男歌手，2025年憑藉其代表作《用背脊唱情歌》斬獲了香港樂壇各大獎項。','https://zh.wikipedia.org/wiki/%E6%B9%AF%E4%BB%A4%E5%B1%B1','2026-04-06 22:18:03','2026-04-06 14:11:56','2026-04-06 14:18:03'),(63,'PH-1','PH1，或稱為克卜勒64b（Kepler-64b）是一顆環繞四重星系統內其中一組聯星的環聯星運轉行星。該行星是由參與行星獵人計畫的兩位業餘天文學家在一組各國天文學家中來自耶魯大學的成員幫助下分析來自克卜勒太空望遠鏡的資料發現。該行星於2012年10月15日宣布發現，是以凌日法在四重星系統中發現的第一顆行星，也是在四重星系統中發現的首顆環聯星運轉行星，更是四重星系統中發現的第一顆行星。該行星也是行星獵人計畫確認發現的第一顆行星。','https://zh.wikipedia.org/wiki/PH1','2026-04-06 22:18:05','2026-04-06 14:11:56','2026-04-06 14:18:05'),(64,'amazarashi','amazarashi是一個創立於日本青森縣的日本搖滾樂團，目前所屬的唱片公司是日本索尼音樂娛樂旗下的Sony Music Associated Records。樂團名稱「amazarashi」是日語「雨曝し」的羅馬拼音，為「曝身於雨中、任風雨摧殘、飽受風霜」之意。主唱秋田弘曾在一次訪談中提到樂團名稱的由來：「將平時的日常裡承受的悲傷與痛楚比喻作雨。儘管我們總是曝身於雨中，仍希望能把『即便如此』的不屈精神給唱出來。」樂團的核心成員為秋田弘與豐川真奈美二人。官方設立的粉絲俱樂部為「APOLOGIES」。','https://zh.wikipedia.org/wiki/Amazarashi','2026-04-06 22:18:07','2026-04-06 14:11:56','2026-04-06 14:18:07'),(65,'Billyrrom','溫蒂漫步 是一組台灣獨立樂團，成立於2018年。2020年發行首張專輯《Spring Spring》。現任成員共五人，分別為主唱兼貝斯手江楊、主唱兼吉他手曾妮、鍵盤兼合成器手李曜如 、吉他手瑋翔以及鼓手阿叡。樂團早期由學生樂團起步，隨後加入經紀公司「睦木文化」，轉型為全職職業音樂人。','https://zh.wikipedia.org/wiki/%E6%BA%AB%E8%92%82%E6%BC%AB%E6%AD%A5','2026-04-06 22:18:09','2026-04-06 14:11:56','2026-04-06 14:18:09'),(66,'丁噹','丁噹（1982年4月17日—），本名吳嫻，中國大陸女歌手，在臺灣出道，被譽為「全民情歌天后」。活躍於大中華地區，丁噹以為偶像劇配唱聞名，演唱歌曲包括《我愛他》《手掌心》《偷偷的愛》《不是你的錯》《好難得》《一個人不可能》。','https://zh.wikipedia.org/wiki/%E4%B8%81%E5%99%B9','2026-04-06 22:18:11','2026-04-06 14:11:56','2026-04-06 14:18:11'),(67,'鄧紫棋','鄧詩穎，藝名鄧紫棋、G.E.M.，香港女創作歌手、詞曲作家與唱片監製。2008年7月10日，以16歲之齡出道，取得香港三大樂壇頒獎禮新人金獎。2012年，發行專輯《Xposed》並奪得香港IFPI成為全年最高銷量香港女歌手，憑藉《Xposed》於2013年入圍第24屆金曲獎最佳女歌手，成為入圍金曲歌后最年輕的女歌手。2014年，因參與湖南衛視歌唱競賽節目《我是歌手》第二季時的亮眼表現在華語地區迅速走紅。','https://zh.wikipedia.org/wiki/%E9%84%A7%E7%B4%AB%E6%A3%8B','2026-04-06 22:18:13','2026-04-06 14:11:56','2026-04-06 14:18:13'),(68,'MONSTA X','MONSTA X，是韓國STARSHIP娛樂於2015年透過與Mnet合作的選秀節目《NO.MERCY》所推出的嘻哈男子音樂組合，是继2011年BOYFRIEND后STARSHIP娛樂时隔4年再次推出的男子偶像团体，最初由七位成員SHOWNU、元虎、玟赫、基現、亨元、周憲、I.M組成，由SHOWNU擔任隊長。2015年5月14日發行首張專輯《TRESPASS》於Mnet《M! Countdown》出道。','https://zh.wikipedia.org/wiki/MONSTA_X','2026-04-06 22:18:16','2026-04-06 14:11:56','2026-04-06 14:18:16'),(69,'SUNNY','李纯揆，藝名珊妮，英文名為Susan Soonkyu Lee，美籍韓裔女歌手、主持人、演員，出生于加利福尼亞州橙市，韓國女子團體少女时代及子团少女時代-Oh! GG成員，隊內擔當領唱。叔叔為SM娛樂創辦人李秀滿。','https://zh.wikipedia.org/wiki/Sunny_(%E5%B0%91%E5%A5%B3%E6%99%82%E4%BB%A3)','2026-04-06 22:18:18','2026-04-06 14:11:56','2026-04-06 14:18:18'),(70,'無','無，是沒有、虛無、空和冇的同義詞，有（存在）的反義詞。在東方哲學中，空可能和無的意義不同，分別屬於佛家和道家的思想。神學與哲學研究無的概念已經有一段時間，例如佛教和道家。數學有時會用無來描述一些狀況。物理學上，没有真正的真空；宇宙誕生带来时间中，没有「宇宙誕生之前」的一个概念，或是宇宙誕生前是虛時間。','https://zh.wikipedia.org/wiki/%E7%84%A1','2026-04-06 22:18:20','2026-04-06 14:11:56','2026-04-06 14:18:20'),(71,'Forest','Forest是「森林」的英語，也可以指：','https://zh.wikipedia.org/wiki/Forest','2026-04-06 22:18:21','2026-04-06 14:11:56','2026-04-06 14:18:21'),(72,'MoonD’shake《Paradise','埃尔维斯·亞伦·普雷斯利，美國搖滾男歌手、演員，被視為20世紀中期最重要的文化符號之一，號稱「搖滾樂之王」 或簡稱「王」。在華語世界，他以外號「貓王」 為人熟知。','https://zh.wikipedia.org/wiki/%E8%89%BE%E7%B6%AD%E6%96%AF%C2%B7%E7%9A%AE%E7%A6%AE%E5%A3%AB%E5%88%A9','2026-04-06 22:18:24','2026-04-06 14:11:56','2026-04-06 14:18:24'),(73,'吉姆hen醉音樂節','拍謝少年是一個來自台灣的台語搖滾樂團，成立於2005年。現任成員為吉他手維尼、貝斯手薑薑及鼓手宗翰。','https://zh.wikipedia.org/wiki/%E6%8B%8D%E8%AC%9D%E5%B0%91%E5%B9%B4','2026-04-06 22:18:26','2026-04-06 14:11:56','2026-04-06 14:18:26'),(74,'MeridiaNight','浠Mizuki，臺灣虛擬YouTuber，隸屬子午計畫，2021年8月28日於YouTube首播出道，直播內容以歌回為主，2022年2月達成10萬人訂閱。','https://zh.wikipedia.org/wiki/%E6%B5%A0Mizuki','2026-04-06 22:18:28','2026-04-06 14:11:56','2026-04-06 14:18:28'),(75,'上岸音樂節','陳忻玥，出生於臺灣臺北市，台灣創作女歌手。肄業於輔仁大學英文系。參加歌唱選秀節目《聲林之王2》後人氣大漲。代表作《煙幕》目前在YouTube觀看次數已累積突破5000萬次，《炙愛》女聲版突破3000萬次，2019年與師兄高爾宣合作的男女對唱版《Without you》也突破2000萬觀看，2022年發行的陳忻玥與李杰明合唱單曲《I\'m alive》亦於2023年4月底突破一千萬點擊，現已突破2000萬次，在2020年9月時舉辦個人專場售票演唱會，並在演唱會上一口氣演唱近20首歌曲，其中也邀請了同門師姐王艷薇、師弟李杰明以及師兄高爾宣擔任嘉賓。','https://zh.wikipedia.org/wiki/%E9%99%B3%E5%BF%BB%E7%8E%A5','2026-04-06 22:18:30','2026-04-06 14:11:56','2026-04-06 14:18:30'),(76,'WAKER','WAKER 是韓國HOWLING娛樂（KINGDOM創辦人創立的新公司）旗下的韓國出道男團，成員為Kohyeon、Kwon Hyeop、Ijun、Leo、Saebyeol、Sebum。出道曲《Atlantis》，並於2023年12月1日在日本展開團體活動，並於2024年1月8日發行首張迷你專輯《Mission of School》正式出道。','https://zh.wikipedia.org/wiki/WAKER','2026-04-06 22:18:32','2026-04-06 14:11:56','2026-04-06 14:18:32'),(77,'Cody・Lee','Cody·Lee (李) 是一個日本的搖滾樂團。所屬的經紀公司是Sony Music Artists，唱片廠牌為Ki/oon Music。','https://zh.wikipedia.org/wiki/Cody%C2%B7Lee_(%E6%9D%8E)','2026-04-06 22:18:34','2026-04-06 14:11:56','2026-04-06 14:18:34'),(78,'秋山黄色','秋山黃色 是一名日本男性創作歌手，出生於日本栃木縣宇都宮市。','https://zh.wikipedia.org/wiki/%E7%A7%8B%E5%B1%B1%E9%BB%83%E8%89%B2','2026-04-06 22:18:36','2026-04-06 14:11:56','2026-04-06 14:18:36'),(82,'Geordie','喬迪 是英國英格蘭東北部泰恩賽德地區民眾的暱稱，也可以指當地民眾使用的英語方言。直到1980年代為止，喬迪一詞可以指任何來自東北英格蘭的人，現在仍有很多人使用這一定義。喬迪方言被視為有強烈的勞工階級色彩。據2008年的一份報紙的調查，喬迪被認為是英格蘭最具吸引力的方言。','https://zh.wikipedia.org/wiki/%E5%96%AC%E8%BF%AA','2026-04-06 22:18:38','2026-04-06 14:11:56','2026-04-06 14:18:38'),(84,'SOUND','Sound原意是「聲音」的英文，也可以指： Sound (樂團)：菲律賓一支樂團。 The Sound：英國一支樂團。 The Sounds：瑞典一支樂團。 The Sounds (芬蘭樂團)：芬蘭一支樂團。 Sound (恐怖地帶專輯) Sound (Beyond專輯) sound 近海','https://zh.wikipedia.org/wiki/Sound','2026-04-06 22:18:40','2026-04-06 14:11:56','2026-04-06 14:18:40'),(86,'林頤原Euan','林頤原，身高175cm，出生於台灣彰化鹿港。台灣搖滾吉他手，音樂人（詞曲、編曲、配樂、製作），畢業於台灣藝術大學戲劇學系，TRASH樂團吉他手兼團長，曾入圍金曲獎、金音獎等，並多次參與MV、廣告、舞台劇及電影演出。','https://zh.wikipedia.org/wiki/%E6%9E%97%E9%A0%A4%E5%8E%9F','2026-04-06 22:18:42','2026-04-06 14:11:56','2026-04-06 14:18:42'),(87,'林鴻宇','林有慧（1973年6月27日—），台灣經紀人，是台灣諧星林光寧女兒，紐約理工學院碩士畢業，從TVBS節目部助理做起，曾任福隆製作公司經紀部經紀人、福隆製作公司負責人葛福鴻特別助理、Baleno創意總監。2006年成立喜鵲娛樂，處理李康宜、錢韋杉、朱孝天經紀事務。現在是蕭敬騰、宋念宇經紀人。','https://zh.wikipedia.org/wiki/%E6%9E%97%E6%9C%89%E6%85%A7','2026-04-06 22:18:44','2026-04-06 14:11:56','2026-04-06 14:18:44'),(88,'VH《邁行》年度專場','搖滾台中 首屆由搖滾開跑音樂社於 2007 年在豐原體育場舉辦，原名為「搖滾台中無限自由音樂節」，2008 年起與臺中市政府合作，自 2009 年開始由市府接手為每年舉辦之音樂節。期待能讓民眾能夠體現臺中市音樂文化質地的美好，同時運用臺中的地理位置優勢、豐沛的文化元素、優秀的音樂人才，持續將「搖滾台中」打造成為臺灣流行音樂不可錯過的盛宴。','https://zh.wikipedia.org/wiki/%E6%90%96%E6%BB%BE%E8%87%BA%E4%B8%AD','2026-04-06 22:18:46','2026-04-06 14:11:56','2026-04-06 14:18:46'),(89,'地下城','地下城与勇士，又称Dungeon & Fighter ；Dungeon and Fighter，日本稱阿拉德戰記，美国称Dungeon Fighter Online（DFO），是一款韩国Neople（后被NEXON收购）开发的2D横板ACT類网络游戏。日本在2009年4月播出了以該遊戲為基礎的電視動畫《Slap-up Party 阿拉德戰记》。 《地下城与勇士》 是有史以来玩家最多、票房最高的电子游戏之一，截至 2023 年 6 月，全球玩家超过 8.5 亿，累计收入超过 220 亿美元。 因此，它跻身历史上最赚钱的娱乐媒体产品之列。','https://zh.wikipedia.org/wiki/%E5%9C%B0%E4%B8%8B%E5%9F%8E%E4%B8%8E%E5%8B%87%E5%A3%AB','2026-04-06 22:18:47','2026-04-06 14:11:56','2026-04-06 14:18:47'),(90,'BIG','Big或BIG可以指： Big (电视剧)，2012年韓國連續劇 飛進未來，1988年科幻喜劇片 BIG集团，比亞克·英厄爾斯创办的公司 艾伦陆军机场的机场代码 BIG (2023年电影)，2023年台湾电影','https://zh.wikipedia.org/wiki/Big','2026-04-06 22:18:49','2026-04-06 14:11:56','2026-04-06 14:18:49'),(91,'SFNT','SFNT是一套標準化的字體資料結構格式。許多常見的字體格式，例如PostScript、TrueType、OpenType、WOFF、SIL Graphite等都使用其作為容器，提供各個字元標準化的定址表、資料結構等。該容器原先是由蘋果公司為了麥金塔電腦上的TrueType字體開發的。SFNT的原意是spline font（樣條字體）或scalable font（可縮放的字體）；該縮寫則來自麥金塔電腦內部用來儲存字體資料的標籤名稱。','https://zh.wikipedia.org/wiki/SFNT','2026-04-06 22:18:52','2026-04-06 14:11:56','2026-04-06 14:18:52'),(92,'國泰世華銀行','國泰世華商業銀行股份有限公司，簡稱國泰世華銀行，為台灣的大型商業銀行之一。','https://zh.wikipedia.org/wiki/%E5%9C%8B%E6%B3%B0%E4%B8%96%E8%8F%AF%E5%95%86%E6%A5%AD%E9%8A%80%E8%A1%8C','2026-04-06 22:18:54','2026-04-06 14:11:56','2026-04-06 14:18:54'),(94,'LM.C','LM.C是日本的一個視覺系樂團，由PIERROT的吉他手Aiji和主唱maya以「新世紀型電子搖滾」為概念所組成。','https://zh.wikipedia.org/wiki/LM.C','2026-04-06 22:18:56','2026-04-06 14:11:56','2026-04-06 14:18:56'),(97,'.28','28（二十八）是27与29之间的自然数。','https://zh.wikipedia.org/wiki/28','2026-04-06 22:18:57','2026-04-06 14:11:57','2026-04-06 14:18:57'),(98,'LIVE','Live可以指： 現場直播，一種電視和電台節目的廣播模式 Live音乐会，一種現場音樂會的形式 Live CD Windows Live Ableton Live LIVE (河合奈保子專輯) LIVE LIVE (NEWS專輯) LIVE (漫畫) Live (韓國電視劇)','https://zh.wikipedia.org/wiki/Live','2026-04-06 22:18:59','2026-04-06 14:11:57','2026-04-06 14:18:59'),(99,'台北站','臺北車站位於臺灣臺北市中正區，為臺鐵、台灣高鐵、台北捷運的地下化鐵路車站，周邊有臺北轉運站等公路客運及市區公車站點，並可經由連通道轉乘機場捷運台北車站。其肩負臺北都市中央車站的功能，並與板橋車站、南港車站並列為臺北都會區三大交通樞紐，也是全台運量最大的鐵路車站。2004年一份統計資料顯示，該站周圍每日進出人次粗略估計數值約為10萬；2013年，一份報導顯示該站總使用人次位居全球各車站排行中第25名。','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8C%97%E8%BB%8A%E7%AB%99','2026-04-06 22:19:01','2026-04-06 14:11:57','2026-04-06 14:19:01'),(102,'10CM','10CM 是韓國一支獨立音樂樂隊，原由權正烈和尹哲種兩位成員組成。以輕快的曲調和活潑的歌詞為主的他們自2010年正式出道以來便成為韓國一支著名的非主流樂隊。','https://zh.wikipedia.org/wiki/10cm','2026-04-06 22:19:03','2026-04-06 14:11:57','2026-04-06 14:19:03'),(104,'DIOR','DIOR大颖（1999年2月26日—），本名陈佳莹，马来西亚创作女歌手、音乐制作人及内容创作者，主要创作华语流行音乐。她以单曲《爱自己更深》开启其音乐生涯，其代表作包括《在加纳共和国离婚》、《如果那通电话有接通》和《节约用爱》等。','https://zh.wikipedia.org/wiki/DIOR%E5%A4%A7%E9%A2%96','2026-04-06 22:19:07','2026-04-06 14:11:57','2026-04-06 14:19:07'),(105,'艾薇Ivy《BORN','李艾薇，馬來西亞女歌手。2019年參加台灣歌唱選秀節目《聲林之王2》，爆炸力又具辨識度的嗓音，獲得許多觀眾喜愛，最終拿下總冠軍。2020年3月，宣布簽約加入喜鵲娛樂。2021年4月16日，發行個人首張音樂專輯《I》。2023年4月14日，發行個人第二張音樂專輯《Start-Up獨角獸》。2025年4月18日，發行個人第三張音樂專輯《當大人》。2025年7月28日宣布簽約加入原音娛樂。','https://zh.wikipedia.org/wiki/%E6%9D%8E%E8%89%BE%E8%96%87','2026-04-06 22:19:09','2026-04-06 14:11:57','2026-04-06 14:19:09'),(107,'春櫻綻放歌謠祭','夏川里美（1973年10月9日—），本名玉木里美，旧姓兼久，早期藝名星美里，日本沖繩縣石垣島原住民（琉球族）出身的歌手，在日本有「心靈歌姬」之稱。1987年獲藤山一郎譽為「四十年才出現一次的歌手」。她擅長演奏沖繩三線，大量出現在她的歌曲中。','https://zh.wikipedia.org/wiki/%E5%A4%8F%E5%B7%9D%E9%87%8C%E7%BE%8E','2026-04-06 22:19:11','2026-04-06 14:11:57','2026-04-06 14:19:11'),(108,'múm','múm，冰島的實驗音樂團體。','https://zh.wikipedia.org/wiki/M%C3%BAm','2026-04-06 22:19:13','2026-04-06 14:11:57','2026-04-06 14:19:13'),(109,'.22','22（二十二）是21与23之间的自然数。','https://zh.wikipedia.org/wiki/22','2026-04-06 22:19:15','2026-04-06 14:11:57','2026-04-06 14:19:15'),(110,'Spoilman','Spoilman 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43'),(111,'.18KIRIS+mini','TPE48 是由日本詞曲作家秋元康擔任總製作人，台灣音樂製作人陳子鴻擔任顧問的臺灣大型女子偶像團體，為女子偶像團體AKB48在海外的姊妹團體之一，以臺北為基地展開活動。於2017年中開始籌備，2018年2月4日團員正式公開亮相；原預計2018年6月在樂壇出道，後來因營運公司發生財務危機，導致活動暂时停止。2018年7月30日，AKB48的營運公司AKS透過媒體宣布解除原營運公司有關TPE48的授權合約，除了接手經營並將團體改名為「AKB48 Team TP」之外，也在台灣成立「好言娛樂有限公司」做為營運單位，之後於同年8月26日首次以新團名正式公開亮相。2026年1月18日，團體宣布將更名回最初團名「TPE48」，於同年1月21日…','https://zh.wikipedia.org/wiki/TPE48','2026-04-06 22:19:22','2026-04-06 14:11:57','2026-04-06 14:19:22'),(113,'台新銀行','台新國際商業銀行，簡稱「台新銀行」、「台新銀」，是一家臺灣大型商業銀行，現為台新新光金控旗下全資擁有的子公司，全臺灣目前共有101家分行，於海外地區設有行銷辦事處。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E6%96%B0%E5%9C%8B%E9%9A%9B%E5%95%86%E6%A5%AD%E9%8A%80%E8%A1%8C','2026-04-06 22:19:24','2026-04-06 14:11:57','2026-04-06 14:19:24'),(114,'▼精靈王座','《龍之谷：破曉奇兵》，是2014年7月31日上映的中國3D动画電影，由宋岳峰擔任導演，Mili Entertainment、華夏電影發行有限責任公司联合發行。本作为网络游戏《龍之谷》前传。','https://zh.wikipedia.org/wiki/%E9%BE%8D%E4%B9%8B%E8%B0%B7%EF%BC%9A%E7%A0%B4%E6%9B%89%E5%A5%87%E5%85%B5','2026-04-06 22:19:26','2026-04-06 14:11:57','2026-04-06 14:19:26'),(117,'ONEW','李珍基，藝名溫流，韓國歌手、演員、主持人，為男子團體SHINee隊長及主唱。','https://zh.wikipedia.org/wiki/%E6%BA%AB%E6%B5%81_(%E9%9F%93%E5%9C%8B)','2026-04-06 22:19:28','2026-04-06 14:11:57','2026-04-06 14:19:28'),(118,'《Word','Microsoft Word，為微軟公司開發的文書處理软件，最初在1983年由理查德·布罗迪为了运行DOS的IBM计算机而编写的，随后的版本可运行于Apple Macintosh（1984年）、SCO UNIX和Microsoft Windows（1989年），并成为了Microsoft Office的一部分。現時最新的版本是Word 2021 for Windows及Word 2021 for Mac。','https://zh.wikipedia.org/wiki/Microsoft_Word','2026-04-06 22:19:30','2026-04-06 14:11:57','2026-04-06 14:19:30'),(119,'Noridogam','2025年Melon音樂獎，即第17届Melon音樂獎。颁奖典礼由Kakao娛樂于2025年12月20日在韩国首尔高尺天空巨蛋举行，通过Melon、Wavve、U-NEXT、Magenta TV、1theK直播播出。','https://zh.wikipedia.org/wiki/2025%E5%B9%B4Melon%E9%9F%B3%E6%A8%82%E7%8D%8E','2026-04-06 22:19:32','2026-04-06 14:11:57','2026-04-06 14:19:32'),(120,'吳宗憲JACKY','吳宗憲演藝作品與事業列表主要介绍台灣藝人吳宗憲歷年的各類型演藝作品和經營事業。','https://zh.wikipedia.org/wiki/%E5%90%B3%E5%AE%97%E6%86%B2%E6%BC%94%E8%97%9D%E4%BD%9C%E5%93%81%E8%88%87%E4%BA%8B%E6%A5%AD%E5%88%97%E8%A1%A8','2026-04-06 22:19:34','2026-04-06 14:11:57','2026-04-06 14:19:34'),(121,'Oneohtrix','《失速夜狂奔》 是一部2017年美國犯罪驚悚片，由班尼·沙夫戴與喬許·沙夫戴執導，喬許·賽佛迪也和羅納德·布朗斯坦共同撰寫劇本。該片的主演包括羅伯·派汀森、珍妮佛·傑森·李、班尼·沙夫戴、巴克哈德·阿卜迪和巴迪·杜里斯等人。','https://zh.wikipedia.org/wiki/%E5%A4%B1%E9%80%9F%E5%A4%9C%E7%8B%82%E5%A5%94','2026-04-06 22:19:38','2026-04-06 14:11:57','2026-04-06 14:19:38'),(122,'陳嫺靜X雲端司機《夏日高峰會','陳嫺靜X雲端司機《夏日高峰會 為本資料庫收錄之演出藝人。近期相關報導包含：陳嫺靜 × 雲端司機「夏日高峰會｜2026亞太區」Legacy Taipei 完售再加場。','https://news.google.com/rss/articles/CBMiS0FVX3lxTE9PRTJoelhEMWNBbmxyVHRCcXdITUJhS2ZmVU5zbERJX3BtQUxLeW14YVh5U1M2TDNQQklkeHhvSzAwNFJMeHhmWDh6Yw?oc=5','2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43'),(123,'教育補助券4合1','《親愛壞蛋》(Lovely Villain) 是2023年TVBS首部原創影集，獲文化部影視及流行音樂產業局108年度（2019年）電視節目製作補助。於2021年11月16日開拍，2022年1月16日殺青。2023年4月21日起，於三立都會台週五十點檔首播，Netflix、LINE TV、Hami Video、中華電信MOD於晚間11點同步上架，TVBS歡樂台則於4月29日，每周六晚間十點播出。','https://zh.wikipedia.org/wiki/%E8%A6%AA%E6%84%9B%E5%A3%9E%E8%9B%8B','2026-04-06 22:19:46','2026-04-06 14:11:57','2026-04-06 14:19:46'),(124,'有補助快搶!','《山中森林》是一部2022年臺灣黑幫電影，由導演姜寧執導，李康生、謝承均、李千娜、邱勝翊、郭雪芙、陳德容、黃遠等人領銜主演，也入選為高雄電影節的閉幕片。原作劇本入圍第43屆優良電影劇本作品。','https://zh.wikipedia.org/wiki/%E5%B1%B1%E4%B8%AD%E6%A3%AE%E6%9E%97','2026-04-06 22:19:47','2026-04-06 14:11:57','2026-04-06 14:19:47'),(127,'《2026','伊朗戰爭 是一場於伊朗及波斯灣沿岸地區爆發的區域性戰爭。2026年2月28日，美国與以色列為推翻伊朗的伊斯兰革命政权，聯合開展預防性軍事行動打擊该国的高官、將領、戰機、戰艦、戰略設施等關鍵目標，更發動斩首空襲擊斃伊朗時任最高領袖阿里·哈梅內伊。伊朗隨後以大量弹道导弹和自杀式无人机還擊，大舉空襲中東域內多個美軍基地及以色列本土，域內多個海灣國家亦有民用設施遭伊朗空襲牽連；同時伊朗亦袭击航經波斯灣主要為油輪的民船，事實上局部封鎖霍爾木茲海峽並嚴重影響全球石油供應。该衝突持续至今已外溢蔓延至黎凡特及印度洋地區，并有陷入胶着的趋势。','https://zh.wikipedia.org/wiki/%E4%BC%8A%E6%9C%97%E6%88%B0%E7%88%AD_(2026%E5%B9%B4)','2026-04-06 22:19:49','2026-04-06 14:11:57','2026-04-06 14:19:49'),(129,'JimmySea','吉达蓬·坡提維赫，昵称Jimmy，為GMMTV旗下男演員、醫生兼模特，因出演《只是朋友啊朋友》而为人熟知。代表作有《反之亦爱》（2022年）、《不曾遺忘的暮色》（2023年）。 其個人粉絲名為「Tiny」。','https://zh.wikipedia.org/wiki/%E5%90%89%E8%BE%BE%E8%93%AC%C2%B7%E5%9D%A1%E6%8F%90%E7%B6%AD%E8%B5%AB','2026-04-06 22:19:51','2026-04-06 14:11:57','2026-04-06 14:19:51'),(131,'KANGIN','SUPER JUNIOR，是韓國SM娱樂於2005年推出的男子音樂團體，和知名女團少女時代並稱是領導韓國文化流行全世界的主要KPOP音樂團體之一。2010年6月22日，韓庚以演员合約糾紛與SM達成和解而退出組合。2015年8月18日，起範因演員合約期滿而正式退出組合（2009年起即宣布淡出）。2017年起，成員强仁与晟敏暂时停止活动；该组合现以9人形式继续活动。2019年7月11日，強仁退出組合，2025年4月30日，晟敏個人與公司合約期滿不續約，但團體是否退出尚未公告。','https://zh.wikipedia.org/wiki/Super_Junior','2026-04-06 22:19:54','2026-04-06 14:11:57','2026-04-06 14:19:54'),(134,'YOU','You是英語的第二人稱代名詞，表示「你」或「你們」。','https://zh.wikipedia.org/wiki/You','2026-04-06 22:19:56','2026-04-06 14:11:57','2026-04-06 14:19:56'),(136,'Plateau','青藏高原，亦稱西藏高原、青康藏高原、海藏高原，是亚洲的高原地区，世界上最高的高原，平均海拔高度4500米，面积250万平方公里，有“世界屋脊”、“雪域高原”和“第三极”之称，是横跨中亚和東亚的巨大高原，其中主要位于中国西部的西藏自治区和青海省，以及在印度拉达克的一部分。它从南向北延伸1,000公里（620英里），从东到西延伸约2,500公里（1,600英里）。广义上的青藏高原除了自身外还包括横断山和喜马拉雅山，西起帕米尔高原，东至横断山脉东部，南至喜马拉雅山脉南缘，北至昆仑山‒祁连山北侧。涵蓋國境有中国西藏自治区、青海省全境、新疆维吾尔自治区、甘肃省、四川省、云南省部分，以及不丹、尼泊尔、拉达克、巴基斯坦、阿富汗、塔吉克斯坦、吉尔…','https://zh.wikipedia.org/wiki/%E9%9D%92%E8%97%8F%E9%AB%98%E5%8E%9F','2026-04-06 22:19:58','2026-04-06 14:11:57','2026-04-06 14:19:58'),(138,'鈴木真海子suzuki','鈴木保奈美，東京都大田区出身，著名日本女演員，於1990年代曾紅極一時。目前隸屬WME IMG經紀公司。','https://zh.wikipedia.org/wiki/%E9%88%B4%E6%9C%A8%E4%BF%9D%E5%A5%88%E7%BE%8E','2026-04-06 22:20:00','2026-04-06 14:11:57','2026-04-06 14:20:00'),(140,'YONA','Girl Crush 是韓國DAM娛樂於2019年推出的四人女子團體組合，成員包括Bomi、Zia、Taeri及Yujin，於2019年4月8日發行首張數位單曲《Memories》出道。2022年，成員Yona退出團體，加入新成員Hayun。2023年3月24日，Taeri退出組合，由新成員Sena補上。','https://zh.wikipedia.org/wiki/Girl_Crush_(%E9%9F%A9%E5%9B%BD%E5%A5%B3%E5%AD%90%E5%9B%A2%E4%BD%93)','2026-04-06 22:20:02','2026-04-06 14:11:57','2026-04-06 14:20:02'),(142,'前島亞美','前島亞美 是日本女性聲優、演員、歌手及女子偶像組合SUPER☆GiRLS的前成員，是12名成員當中最年輕的。出身自埼玉縣，血型B型，身高164公分。原隸屬於愛貝克思管理，現隸屬於VOICE KIT。','https://zh.wikipedia.org/wiki/%E5%89%8D%E5%B3%B6%E4%BA%9E%E7%BE%8E','2026-04-06 22:20:04','2026-04-06 14:11:57','2026-04-06 14:20:04'),(143,'陳一豪','陳豪，男，祖籍广东台山，香港演員，現為無綫電視經理人合約藝員，於2007年及2023年兩度奪得《萬千星輝頒獎典禮》「最佳男主角」。妻子是前無綫電視藝員陳茵媺。','https://zh.wikipedia.org/wiki/%E9%99%B3%E8%B1%AA_(%E6%BC%94%E5%93%A1)','2026-04-06 22:20:06','2026-04-06 14:11:57','2026-04-06 14:20:06'),(144,'ONE','ONE或one可以指：','https://zh.wikipedia.org/wiki/ONE','2026-04-06 22:20:08','2026-04-06 14:11:57','2026-04-06 14:20:08'),(145,'Beyond','Beyond是一支香港搖滾樂團，1983年成立，原為地下樂隊，於1987年開始邁入香港主流樂壇，其後憑著多首膾炙人口的經典歌曲如《大地》、《真的愛你》、《光輝歲月》、《海闊天空》等成為華語樂壇其中一隊最具影響力的香港樂隊。樂隊成立以來以原創歌曲為賣點，在香港樂壇盛行改編歌曲的時期，Beyond各成員藉著自己創作的音樂作品走紅於香港樂壇，並通過編制包裝和曲風迎合主流使其普及。','https://zh.wikipedia.org/wiki/Beyond','2026-04-06 22:20:10','2026-04-06 14:11:57','2026-04-06 14:20:10'),(149,'May’n','May\'n，本名中林芽依（結婚後是長澤芽依），是名古屋出身的日本女歌手。在2003年由Horipro举办的第28回新人选拔赛中，在34911名候选者中脱颖而出晋级四强，在之后和公司成功签约，并以本名发行过数张唱片。2008年1月宣布採用現今藝名，並在电视动画超时空要塞 Frontier中，担任片中角色银河歌姫雪露·诺姆的歌曲演唱工作。在电视动画三国演义中，演唱日文版主题曲《愛は降る星のごとく》。','https://zh.wikipedia.org/wiki/May\'n','2026-04-06 22:20:12','2026-04-06 14:11:57','2026-04-06 14:20:12'),(150,'Sweet','Sweet可以指： SWEET (TXT專輯)','https://zh.wikipedia.org/wiki/Sweet','2026-04-06 22:20:13','2026-04-06 14:11:57','2026-04-06 14:20:13'),(151,'五月五日','5月5日是阳历年的第125天（闰年是126天），离一年的结束还有240天。','https://zh.wikipedia.org/wiki/5%E6%9C%885%E6%97%A5','2026-04-06 22:20:15','2026-04-06 14:11:57','2026-04-06 14:20:15'),(152,'張貝芝','張柏芝，本名張栢芝，香港女演員。1999年以電影《喜剧之王》出道並走紅。2004年，凭借電影《忘不了》获得第二十三届香港电影金像奖最佳女主角奖。其他电影代表作有：《星愿》（1999），《河东狮吼》（2003），《大隻佬》（2003）。','https://zh.wikipedia.org/wiki/%E5%BC%B5%E6%9F%8F%E8%8A%9D','2026-04-06 22:20:17','2026-04-06 14:11:57','2026-04-06 14:20:17'),(153,'Vinz','〈I Wanna Know〉是瑞典音樂人Alesso和臺灣歌手蔡依林的歌曲。該歌曲由蔡依林、Alessandro Lindblad、Kahouly Nicolay Sereba、Vincent Dery及Ozzy Jaquesson Sowe創作、Alessandro Lindblad製作。該歌曲於2016年9月30日由凌時差音樂和Amy Thomson Management以單曲形式發行。','https://zh.wikipedia.org/wiki/I_Wanna_Know','2026-04-06 22:20:19','2026-04-06 14:11:57','2026-04-06 14:20:19'),(154,'Apink','Apink 是韓國IST娛樂於2011年推出的K-pop女子音樂團體，現任成員包括：朴初瓏、尹普美、鄭恩地、金南珠、吳夏榮，由朴初瓏擔任隊長。團體曾榮获首尔歌谣大赏、金唱片奖、MAMA大獎等多个奖项。','https://zh.wikipedia.org/wiki/Apink','2026-04-06 22:20:21','2026-04-06 14:11:57','2026-04-06 14:20:21'),(155,'Nelson′s','纳尔逊，或译纳尔森，可指：','https://zh.wikipedia.org/wiki/%E7%BA%B3%E5%B0%94%E9%80%8A','2026-04-06 22:20:24','2026-04-06 14:11:57','2026-04-06 14:20:24'),(156,'KKTIX','KKTIX活動報名售票平台是一家台灣的線上售票網站。前身為 2007年9月 成立的 Registrano，2013年10月31日轉移到 KKBOX 旗下並改名為 KKTIX。','https://zh.wikipedia.org/wiki/KKTIX','2026-04-06 22:20:26','2026-04-06 14:11:57','2026-04-06 14:20:26'),(159,'Organik','罗伯托·孔奇纳 （1969年11月3日—2017年5月9日）, 其艺名为罗伯特·迈尔斯 是一位意大利唱片制作人、作曲家、音乐家和唱片骑师（DJ）。 他于1995年创作的歌曲《Children》销量超过500万张，位居全球排行榜榜首。','https://zh.wikipedia.org/wiki/%E7%BD%97%E4%BC%AF%E7%89%B9%C2%B7%E8%BF%88%E5%B0%94%E6%96%AF','2026-04-06 22:20:28','2026-04-06 14:11:57','2026-04-06 14:20:28'),(160,'上原廣美與音速奇景','上原廣美與音速奇景 為本資料庫收錄之演出藝人。近期相關報導包含：TREASURE、NCT WISH、吳宗憲、炎亞綸、李帝勳⋯本周演唱會快報！時間地點、入場須知速看｜本周想見你3/24~3/29。','https://news.google.#3b2027a87c1911f9','2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43'),(161,'JID','謎幻樂團 是一個成立於美國內華達州拉斯維加斯的獨立搖滾樂團。','https://zh.wikipedia.org/wiki/%E8%AC%8E%E5%B9%BB%E6%A8%82%E5%9C%98','2026-04-06 22:20:37','2026-04-06 14:11:57','2026-04-06 14:20:37'),(166,'信樂團2026信念不滅','信，本名蘇見信，出生于臺灣臺北市。台灣華語流行音樂男歌手，曾擔任信樂團第一任主唱。2002年，擔任信樂團主唱，以高亢嘶吼歌唱技巧走紅。於2007年單飛，發行個人專輯《我就是我》。近年陸續在2016年參加湖南衛視《我是歌手第四季》，最近於2019年發行全新專輯《煉金術》。','https://zh.wikipedia.org/wiki/%E4%BF%A1_(%E6%AD%8C%E6%89%8B)','2026-04-06 22:20:40','2026-04-06 14:11:57','2026-04-06 14:20:40'),(167,'山本彩','山本彩 是日本女藝人、創作歌手，為女子偶像團體NMB48 Team N前成員，曾為Team N隊長與NMB48總隊長，大阪府出身，所屬經紀公司為SYCompany。2011年以NMB48一期生身分出道。2014年至2016年5月間兼任AKB48 Team K成員。2018年11月4日自NMB48畢業，在籍期間被譽為NMB48的中心人物。在加入NMB48前，曾是2008年出道、但已解散的女子搖滾樂團MAD CATZ的成員之一。','https://zh.wikipedia.org/wiki/%E5%B1%B1%E6%9C%AC%E5%BD%A9','2026-04-06 22:20:42','2026-04-06 14:11:57','2026-04-06 14:20:42'),(168,'Chiai','藤川千爱，日本歌手，出生于冈山县後月郡芳井町。','https://zh.wikipedia.org/wiki/%E8%97%A4%E5%B7%9D%E5%8D%83%E7%88%B1','2026-04-06 22:20:44','2026-04-06 14:11:57','2026-04-06 14:20:44'),(170,'Chance','朴贊郁，韓國電影導演。「PARKing CHANce」是他與弟弟的合稱。','https://zh.wikipedia.org/wiki/%E6%9C%B4%E8%B4%8A%E9%83%81','2026-04-06 22:20:46','2026-04-06 14:11:57','2026-04-06 14:20:46'),(174,'INHON','王謙 Goatak，本名王謙，台灣新生代創作歌手、製作人。20歲時以《What Can I?》、《Dice》、《Can You Feel》等熱門單曲走進大眾視野，早期創作多以龐克搖滾結合陷阱音樂節奏的情緒饒舌emo rap曲風為主，而在2022年的新專輯《BeLiving》中曲風轉變為以00後的流行樂結合電子合成器，帶給聽眾不同的感受。','https://zh.wikipedia.org/wiki/%E7%8E%8B%E8%AC%99Goatak','2026-04-06 22:20:48','2026-04-06 14:11:57','2026-04-06 14:20:48'),(175,'BanG','《BanG Dream!》，簡稱“Bandori!”（バンドリ!），是以連載於《月刊武士道》的同名漫畫作品為基礎的日本跨媒體製作企劃，該漫畫由中村航原作、石田彩作畫，並由ひと和負責人物設定，故事描述女高中生的樂團活動。除漫畫外，《BanG Dream!》還包括電視動畫系列、現場演唱會、單曲與專輯、VTuber，以及由Craft Egg開發的手機節奏遊戲《BanG Dream! 少女樂團派對》。','https://zh.wikipedia.org/wiki/BanG_Dream!','2026-04-06 22:20:50','2026-04-06 14:11:57','2026-04-06 14:20:50'),(176,'鮑比達與朋友們','《狸想世界》 是一部2026年美國動畫科幻喜劇片，由皮克斯動畫工作室製作，華特迪士尼工作室電影發行，丹尼爾·鍾執導並與傑西·安德魯斯共同編劇，派珀·柯達、鮑比·莫尼漢、喬·漢姆、凱茜·納基麥和戴夫·法蘭科為角色配音。電影講述一名熱愛動物的女孩意識被轉移到一隻栩栩如生的機器海狸體內，以便與動物交流並拯救棲息地免遭破壞，卻無意中引發了一場動物起義。','https://zh.wikipedia.org/wiki/%E7%8B%B8%E6%83%B3%E4%B8%96%E7%95%8C','2026-04-06 22:20:52','2026-04-06 14:11:57','2026-04-06 14:20:52'),(177,'SAY','SAY MY NAME，簡稱SMN，是韓國iNKODE於2024年推出的八人女子音樂團體，原先由HITOMI、MEI、KANNY、SOHA、DOHEE、JUNHWI、SEUNGJOO七人組成，2025年7月10日，加入新成員SHUIE成為八人組合。','https://zh.wikipedia.org/wiki/SAY_MY_NAME','2026-04-06 22:20:55','2026-04-06 14:11:57','2026-04-06 14:20:55'),(180,'PEBACA','阿塔潘·彭萨瓦，小名Gun，泰國男演員，童星出身。','https://zh.wikipedia.org/wiki/%E9%98%BF%E5%A1%94%E6%BD%98%C2%B7%E5%BD%AD%E8%90%A8%E7%93%A6','2026-04-06 22:20:57','2026-04-06 14:11:57','2026-04-06 14:20:57'),(182,'TALES','Tales 可以指：','https://zh.wikipedia.org/wiki/Tales','2026-04-06 22:20:59','2026-04-06 14:11:57','2026-04-06 14:20:59'),(183,'marasy','觸手猴 是日本鋼琴演奏家、作詞家、作曲家。因在YouTube和niconico動畫投稿而為人們所知。YouTube訂閱人數於2024年12月31日超過200萬人。','https://zh.wikipedia.org/wiki/%E8%A7%B8%E6%89%8B%E7%8C%B4','2026-04-06 22:21:01','2026-04-06 14:11:57','2026-04-06 14:21:01'),(185,'Vansdaddy','Vansdaddy 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43'),(187,'六道鬼門','六道，又名六趣 、六凡、六途或轮回六道等，佛教名詞，意指六種欲界、色界及無色界眾生的種類型態或者說是境界，也是在凡夫众生轮回之道途，它是佛教宇宙觀的一部份。六道（六凡）屬於十法界（十界），和四聖合稱為“四聖六凡”。','https://zh.wikipedia.org/wiki/%E5%85%AD%E9%81%93','2026-04-06 22:21:08','2026-04-06 14:11:57','2026-04-06 14:21:08'),(188,'NI','Ni或NI可以指： 镍，一种金属元素 美国国家仪器公司，英語：National Instruments 无所属议员，指歐洲議會裡不隸屬於任何一個黨團的議員','https://zh.wikipedia.org/wiki/Ni','2026-04-06 22:21:10','2026-04-06 14:11:57','2026-04-06 14:21:10'),(189,'高雄站','高雄車站，或稱高雄火車站 、高雄車頭，常被簡稱為「高火」，位於高雄市三民區，為臺灣鐵路公司及高雄捷運的地下化鐵路車站。該站為臺鐵縱貫線南段與屏東線及高雄捷運紅線的連接點，位處高雄市兩大城鎮左營跟鳳山的中心，且為高雄市區最重要的鐵路車站，也是高雄都會區與南臺灣重要的交通轉運樞紐。車站在地下化之前向外延伸之鐵軌也常被居民用來劃分北高雄、南高雄的市區區域。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E8%BB%8A%E7%AB%99','2026-04-06 22:21:11','2026-04-06 14:11:57','2026-04-06 14:21:11'),(191,'TAKASE','高瀨統也 是一位日本音樂家和創作歌手。他的本名也是高瀬統也。出生於日本愛知縣扶桑町。身高為178cm，血型為A型。推出的歌曲接近全部都自行參與了作曲、作詞。為配合不同歌曲，他還會彈結他和電子琴。','https://zh.wikipedia.org/wiki/%E9%AB%98%E7%80%A8%E7%B5%B1%E4%B9%9F','2026-04-06 22:21:14','2026-04-06 14:11:57','2026-04-06 14:21:14'),(194,'JOY','Joy可以指： 快樂，情緒。joyful為其形容詞。','https://zh.wikipedia.org/wiki/Joy','2026-04-06 22:21:16','2026-04-06 14:11:57','2026-04-06 14:21:16'),(195,'CNBLUE','CNBLUE，韓國FNC娛樂旗下的樂團組合，2009年成立。成員包括鄭容和、姜敏赫和李正信組成。首位貝斯手權光珍2009年在日語《Now or Never》發行後退出，由李正信接手。李宗泫2019年退出。','https://zh.wikipedia.org/wiki/CNBLUE','2026-04-06 22:21:17','2026-04-06 14:11:57','2026-04-06 14:21:17'),(196,'小林未郁','小林未郁，日本女创作歌手，出身於广岛县。其身高為150cm。其血型为AB型。','https://zh.wikipedia.org/wiki/%E5%B0%8F%E6%9E%97%E6%9C%AA%E9%83%81','2026-04-06 22:21:19','2026-04-06 14:11:57','2026-04-06 14:21:19'),(197,'雪国','《雪国》， 是日本作家川端康成的第一部中篇小說，全書不到8萬字（日文）。 它也是作者在被授予諾貝爾文學獎時，評獎委員提到的三部小說之一。 另外兩部是《古都》和《千羽鶴》。 題目中的“國”是地區、鄉鎮的意思，所以中文譯本也有做《雪鄉》的，如蕭羽文或金溟若的譯本。 但維持《雪國》名稱的中文譯本更普遍一些，如韓侍桁或葉渭渠、唐月梅夫婦的譯本。','https://zh.wikipedia.org/wiki/%E9%9B%AA%E5%9B%BD','2026-04-06 22:21:21','2026-04-06 14:11:57','2026-04-06 14:21:21'),(199,'獨書祭','姚廣孝（1335年—1418年），幼名天禧，賜名廣孝，法名道衍，字斯道，又字獨闇，庵號獨庵（獨菴），號獨庵老人、逃虛子，通稱姚道衍。江浙等處行中書省平江路（明为南直隶苏州府）長洲縣（今江苏省苏州市）人，祖籍开封府汴梁（一說為福州府長樂縣）。中国元末明初政治人物、 臨濟宗僧人、詩人，明成祖靖难之役的叛臣之一，亦為協助朱棣篡位奪權的第一功臣。','https://zh.wikipedia.org/wiki/%E5%A7%9A%E5%BB%A3%E5%AD%9D','2026-04-06 22:21:23','2026-04-06 14:11:57','2026-04-06 14:21:23'),(202,'luv','〈LUV〉是韓國女子團體Apink的一首歌曲。於2014年11月24日作為她們第五張迷你專輯《Pink LUV》的主打歌發行，並於2015年5月20日在日本作為單曲發行。歌曲以「初戀」為核心意象，描繪那種人人一生至少會體會一次的青澀情感。值得一提的是，這首歌也是K-pop史上在各大音樂節目中奪得最多一位的女團歌曲，共奪得17個一位。','https://zh.wikipedia.org/wiki/LUV','2026-04-06 22:21:25','2026-04-06 14:11:57','2026-04-06 14:21:25'),(203,'無限MAX紋身音樂節','金孝靜（韓語：김효정，羅馬化：Kim Hyo Jung，1991年1月11日—)，藝名孝琳（韓語：효린，羅馬化：Hyo Rin，英語：Hyo Lyn)，是一位韓國K-pop女歌手與舞者，孝琳有撩人和極具有爆发力的悅耳歌聲以及性感的风格，拥有「韩国和亞洲的碧昂丝」的美譽，同時也是韓國STARSHIP娛樂著名女團SISTAR的隊長和主唱。','https://zh.wikipedia.org/wiki/%E5%AD%9D%E7%90%B3','2026-04-06 22:21:27','2026-04-06 14:11:57','2026-04-06 14:21:27'),(204,'Framed','《谁陷害了兔子罗杰》 是1988年的美国奇幻喜剧片，由罗伯特·泽米基斯执导，根据格瑞·沃尔夫的同名小说改编，弗兰克·马歇尔和罗伯特·瓦兹提任制片人。影片由真人演员和动画角色共同出演，营造两者直接互动的神奇世界。华特迪士尼公司1981年买下小说电影改编版权，编剧杰夫瑞·普莱斯和彼得·西曼在迪斯尼公司请来史蒂文·斯皮尔伯格担任执行制片人并与安布林娱乐公司一起为影片提供资金支持前就已经写出两稿剧本。电影主要演员包括鲍勃·霍斯金斯、克里斯托弗·洛伊德（配音）、凯瑟琳·特纳（配音）和安娜·卡西迪。','https://zh.wikipedia.org/wiki/%E8%B0%81%E9%99%B7%E5%AE%B3%E4%BA%86%E5%85%94%E5%AD%90%E7%BD%97%E6%9D%B0','2026-04-06 22:21:31','2026-04-06 14:11:57','2026-04-06 14:21:31'),(205,'黑鹿季雪','白夢妍（1994年9月23日—），藝名白鹿，中國大陸女演員。於2024年艺术系列评审工作中，荣获三級演員稱號。','https://zh.wikipedia.org/wiki/%E7%99%BD%E9%B9%BF_(%E6%BC%94%E5%93%A1)','2026-04-06 22:21:33','2026-04-06 14:11:57','2026-04-06 14:21:33'),(206,'KYAS','二硫代铁酸钾是一种无机化合物，化学式为KFeS2。它是紫色难溶于水的固体，其结构由链状的FeS4阴离子四面体和钾离子组成。它可由铁粉、硫和碳酸钾在900 °C反应得到： 6 Fe + 13 S + 4 K2CO3 → 6 KFeS2 + K2SO4 + 4 CO2','https://zh.wikipedia.org/wiki/%E4%BA%8C%E7%A1%AB%E4%BB%A3%E9%93%81%E9%85%B8%E9%92%BE','2026-04-06 22:21:36','2026-04-06 14:11:57','2026-04-06 14:21:36'),(207,'Alan','艾伦是Allen与Alan人名的音译，也译为阿兰，阿伦和爱伦','https://zh.wikipedia.org/wiki/%E8%89%BE%E4%BC%A6','2026-04-06 22:21:37','2026-04-06 14:11:57','2026-04-06 14:21:37'),(212,'富邦金控','富邦金融控股股份有限公司，通稱富邦金控，是臺灣的大型金融控股公司，在韓國首爾擁有分公司。富邦金控以台北富邦商業銀行、富邦產物保險 、富邦人壽保險、富邦綜合證券、富邦投資信託為核心企業。旗下營業據點總計約400處，客戶人數超過1,350萬人。','https://zh.wikipedia.org/wiki/%E5%AF%8C%E9%82%A6%E9%87%91%E8%9E%8D%E6%8E%A7%E8%82%A1','2026-04-06 22:21:39','2026-04-06 14:11:57','2026-04-06 14:21:39'),(214,'eill','《東京復仇者》 是改編自和久井健的同名漫畫的電視動畫，第1期於2021年4月至9月在每日放送、東京電視網播出;第2期「聖夜決戰篇」於2023年1月至4月播出；第3期「天竺篇」於同年10月至12月播出;第4期「三天戰爭篇」預定於2026年10月播出。','https://zh.wikipedia.org/wiki/%E6%9D%B1%E4%BA%AC%E5%BE%A9%E4%BB%87%E8%80%85_(%E5%8B%95%E7%95%AB)','2026-04-06 22:21:42','2026-04-06 14:11:57','2026-04-06 14:21:42'),(218,'AIMI','愛美，本名寺川愛美，是日本的女性聲優、歌手，所屬事务所为響，兵庫縣出身，血型A型。','https://zh.wikipedia.org/wiki/%E6%84%9B%E7%BE%8E','2026-04-06 22:21:43','2026-04-06 14:11:57','2026-04-06 14:21:43'),(219,'EUNHYUK','李赫宰，藝名銀赫，韓國男歌手、主持人及舞台導演，為韓國男子團體Super Junior及子團Super Junior-T、Super Junior-Happy、Super Junior-M、Super Junior-D&E的成员，在隊內擔任主Rapper、主舞。','https://zh.wikipedia.org/wiki/%E9%8A%80%E8%B5%AB','2026-04-06 22:21:45','2026-04-06 14:11:57','2026-04-06 14:21:45'),(220,'歌劇魅影','《歌劇魅影》 是法國作家卡斯頓·勒胡創作的小說。該書於1909年9月23日至1910年1月8日首先在《高盧人報》以連載形式刊登，並於1910年3月下旬由皮埃爾·拉菲特集結成冊出版。','https://zh.wikipedia.org/wiki/%E6%AD%8C%E5%8A%87%E9%AD%85%E5%BD%B1','2026-04-06 22:21:47','2026-04-06 14:11:57','2026-04-06 14:21:47'),(221,'辛曉琪','辛曉琪，台灣女歌手，被稱為“療傷歌后”。曾三度提名金曲獎最佳國語女演唱人獎。','https://zh.wikipedia.org/wiki/%E8%BE%9B%E6%9B%89%E7%90%AA','2026-04-06 22:21:49','2026-04-06 14:11:57','2026-04-06 14:21:49'),(222,'李翊君','李翊君（1969年4月27日—），本名李華苓，台灣女歌手，以精通國語歌和台語歌見稱。為多部瓊瑤電視連續劇演唱過主題曲、片尾曲、插曲。','https://zh.wikipedia.org/wiki/%E6%9D%8E%E7%BF%8A%E5%90%9B','2026-04-06 22:21:51','2026-04-06 14:11:57','2026-04-06 14:21:51'),(223,'AiNA THE END 2026「PICNIC」巡迴','《Love Live!》是矢立肇與公野櫻子創作的日本跨媒體作品系列。','https://zh.wikipedia.org/wiki/Love_Live!%E9%9F%B3%E6%A8%82%E4%BD%9C%E5%93%81%E5%88%97%E8%A1%A8','2026-04-06 22:21:53','2026-04-06 14:11:57','2026-04-06 14:21:53'),(224,'萬世巨星','萬世巨星可以指： 耶穌基督超級巨星，又譯「萬世巨星」，1970年的音樂劇。 萬世巨星，1973年美國的音樂電影，根據上述的音樂劇改編。 萬世巨星，香港商業電台節目。','https://zh.wikipedia.org/wiki/%E8%90%AC%E4%B8%96%E5%B7%A8%E6%98%9F','2026-04-06 22:21:55','2026-04-06 14:11:57','2026-04-06 14:21:55'),(225,'施孝榮','施孝榮（1959年7月6日—），臺灣校園民歌歌手，活躍於1980年代初至中期。〈俠客〉、〈歸人沙城〉、〈拜訪春天〉均為其知名歌曲。','https://zh.wikipedia.org/wiki/%E6%96%BD%E5%AD%9D%E6%A6%AE','2026-04-06 22:21:57','2026-04-06 14:11:57','2026-04-06 14:21:57'),(226,'薛恩Sean','西恩·贾斯汀·潘，美国男演员、導演和政治活動家。他在2003年電影《神秘河流》、2008年傳記電影《自由大道》和2025年電影《一戰再戰》中的演出為自己贏得了三座奧斯卡金像獎，亦曾在金球獎和歐洲三大影展中奪得最佳男主角獎。','https://zh.wikipedia.org/wiki/%E8%A5%BF%E6%81%A9%C2%B7%E6%BD%98','2026-04-06 22:22:02','2026-04-06 14:11:57','2026-04-06 14:22:02'),(227,'藤原櫻','藤原櫻，日本創作歌手、演員。隸屬的經紀公司為Amuse。','https://zh.wikipedia.org/wiki/%E8%97%A4%E5%8E%9F%E6%AB%BB','2026-04-06 22:22:05','2026-04-06 14:11:57','2026-04-06 14:22:05'),(228,'豐田裕大','豐田汽車公司，簡稱豐田 是日本的跨國汽車公司，豐田亦是凌志（LEXUS）、大發（Daihatsu）、日野（HINO）、世紀（CENTURY）品牌的母公司，並以20%股份成為速霸陸的最大股東。','https://zh.wikipedia.org/wiki/%E4%B8%B0%E7%94%B0%E6%B1%BD%E8%BD%A6','2026-04-06 22:22:07','2026-04-06 14:11:57','2026-04-06 14:22:07'),(229,'The Sweet Escape','阿肯，原名阿利奧姆·達馬拉·巴德拉·阿肯·蒂亞姆，嘻哈及R&B歌手、詞曲作家及音樂製作人。Akon於2004年憑首張專輯Trouble中的單曲《Locked Up》而開始受人認識，其後的專輯Konvicted中的單曲《Smack That》更令他獲得葛萊美獎提名。他於Billboard Hot 100中擁有130首客串歌曲及18首單曲的紀錄，亦是史上第一位同時佔據兩次Billboard Hot 100第1及第2位的藝人。','https://zh.wikipedia.org/wiki/%E9%98%BF%E8%82%AF','2026-04-06 22:22:09','2026-04-06 14:11:57','2026-04-06 14:22:09'),(230,'Jane Yeh','葉公超（1904年10月20日—1981年11月20日），原名葉崇智，字公超，後以字行，祖籍浙江余姚，廣東番禺人，生於江西九江。中國學者暨外交家，新月派代表人物之一。曾任北京大學、清華大學外文系教授，上海國立暨南大學、西南聯大外文系主任，中華民國外交部長（1949年－1958年）、駐美大使（1958年－1961年）、新埔工業專科學校（現聖約翰科技大學前身）代理董事長、總統府資政。','https://zh.wikipedia.org/wiki/%E8%91%89%E5%85%AC%E8%B6%85','2026-04-06 22:22:11','2026-04-06 14:11:57','2026-04-06 14:22:11'),(231,'KAO SUPASSARA','素帕薩拉提·阿卡拉塔威帕，曾用名素帕莎拉·塔纳查，小名Kao，泰國女演員兼模特。2013年，在《荷爾蒙》電視劇系列飾演Sprite一角而人氣竄升。','https://zh.wikipedia.org/wiki/%E7%B4%A0%E5%B8%95%E8%96%A9%E6%8B%89%E6%8F%90%C2%B7%E9%98%BF%E5%8D%A1%E6%8B%89%E5%A1%94%E5%A8%81%E5%B8%95','2026-04-06 22:22:13','2026-04-06 14:11:57','2026-04-06 14:22:13'),(232,'Tk Nur','ISO 3166-2:AF是阿富汗在标准ISO 3166-2中的条目。ISO 3166-2为国际标准化组织（ISO）制定的标准ISO 3166的一部分，它定义了标准ISO 3166-1中所有国家主要行政区 的代码。','https://zh.wikipedia.org/wiki/ISO_3166-2%3AAF','2026-04-06 22:22:15','2026-04-06 14:11:57','2026-04-06 14:22:15'),(233,'BALLISTIK BOYZ','BALLISTIK BOYZ from EXILE TRIBE 是隸屬LDH JAPAN的7人男子音樂組合，為放浪一族組成團體中首個全員兼任唱跳的隊伍。所屬唱片公司為LDH Records。','https://zh.wikipedia.org/wiki/BALLISTIK_BOYZ_from_EXILE_TRIBE','2026-04-06 22:22:17','2026-04-06 14:11:57','2026-04-06 14:22:17'),(234,'Hammer Head Shark Asia Tour','Christian \"Flake\" Lorenz is a German musician. He is best known as the keyboardist in Neue Deutsche Härte band Rammstein, as well as the main composer of the band\'s songs along with guitarist Richard Kruspe. He was also a member of the East German punk band Feeling B.','https://en.wikipedia.org/wiki/Christian_Lorenz','2026-04-06 22:22:20','2026-04-06 14:11:57','2026-04-06 14:22:20'),(235,'hitohira','《女優大試煉》（又譯初瓣）是由桐原和泉創作的的一部日本漫畫，連載於雙葉社所發行的漫畫雜誌上，在台灣則是由長鴻出版社代理中文版。','https://zh.wikipedia.org/wiki/%E5%A5%B3%E5%84%AA%E5%A4%A7%E8%A9%A6%E7%85%89','2026-04-06 22:22:22','2026-04-06 14:11:57','2026-04-06 14:22:22'),(236,'deca joins','deca joins是一個台灣的另類搖滾獨立樂團，目前成員為鄭敬儒（主唱、吉他）、楊尚樺（吉他）、謝俊彥 、陸浩釗 (鼓手)、杜哲欣 (打擊樂器)。','https://zh.wikipedia.org/wiki/Deca_joins','2026-04-06 22:22:24','2026-04-06 14:11:57','2026-04-06 14:22:24'),(237,'韋禮安','韋禮安，臺灣創作男歌手。2006年底報名參加華視《快樂星期天》在國立臺灣大學舉辦的第一屆〈校園歌喉戰〉，冠軍賽以一曲《You\'re beautiful》奪得總冠軍。2011年入圍第22屆金曲獎最佳華語男歌手獎、最佳新人獎、最佳華語專輯獎及最佳作曲人獎，最終奪得最佳新人獎；2015年奪得第26屆金曲獎最佳作曲人獎。','https://zh.wikipedia.org/wiki/%E9%9F%8B%E7%A6%AE%E5%AE%89','2026-04-06 22:22:26','2026-04-06 14:11:57','2026-04-06 14:22:26'),(238,'孫淑媚','孫淑媚（1981年1月9日—），臺灣台語女歌手，出生於臺灣高雄市梓官區。國中時期參加三立電視《21世紀新人歌唱排行榜》，以純熟的唱腔連續衛冕20關，隨後與大旗唱片簽約踏入歌壇。2005年以《愛到坎站》獲得第16屆金曲獎最佳台語女演唱人獎。','https://zh.wikipedia.org/wiki/%E5%AD%AB%E6%B7%91%E5%AA%9A','2026-04-06 22:22:28','2026-04-06 14:11:57','2026-04-06 14:22:28'),(239,'蘇永康','蘇永康，香港男歌手、演員兼節目主持，曾參與多部電視劇及電影演出。1985年，參加無綫電視與華星唱片合辦的第四屆《新秀歌唱大賽》奪得亞軍，並簽約華星唱片而涉足娛樂圈。1989年，獲得商業電台及香港電台所頒發的兩台新人獎項。1998年，憑「首本名曲」《越吻越傷心》在多個樂壇頒獎典禮奪得金曲獎項，於《十大中文金曲頒獎音樂會》奪得「全球華人至尊金曲獎」兼「優秀流行歌手大獎」，以及於《叱咤樂壇流行榜頒獎典禮》奪得「叱咤樂壇至尊歌曲大獎」及「叱咤樂壇我最喜愛的歌曲大獎」，躋身一線歌手之列。2011年，憑《那誰》再度奪得「全球華人至尊金曲獎」。2025年，蘇永康擔任無綫電視歌唱選秀節目《聲秀》導師。此外，蘇永康現時也擔任香港星級歌唱學院客席星級…','https://zh.wikipedia.org/wiki/%E8%98%87%E6%B0%B8%E5%BA%B7','2026-04-06 22:22:31','2026-04-06 14:11:57','2026-04-06 14:22:31'),(240,'真愛秀．藍寶石大歌廳','藍寶石大歌廳是臺灣秀場文化的重要符號之一，位於高雄市新興區八德二路與同愛街上，由裝潢者李再富（台北仔）裝潢，為大高雄地區扮演西元1970年代到1980年代娛樂文化的山頭之一。藍寶石大歌廳成立於1967年，至1995年結束營業，創始者蔡有望與其妻陳鶯合力經營，曾經轟動全台及東南亞。當年老三台歌手想盡辦法求經紀人看能否上一檔藍寶石的秀，歌手間有著「沒上過藍寶石，要紅成為歌星很困難」的共識，而且只要在藍寶石歌廳演出過後，回北部以後的演出之後「身價」酬勞價碼也會提升兩三倍以上，所以多位歌星都會爭認歌廳老闆「陳鶯」為乾媽。藍寶石經營久了，終不敵歌星回來演出的價錢漲了兩三倍，原因是隔街有766個座位的今日大歌廳加入，引起爭星戰。陳鶯特請「裝潢…','https://zh.wikipedia.org/wiki/%E8%97%8D%E5%AF%B6%E7%9F%B3%E5%A4%A7%E6%AD%8C%E5%BB%B3','2026-04-06 22:22:32','2026-04-06 14:11:57','2026-04-06 14:22:32'),(241,'THE MUSIC OF SQUARE ENIX－Magic','《寄生都市》 是由Square 開發並於1998年發行的生存恐怖題材動作角色扮演遊戲。本遊戲是小說《寄生前夜》的續集，由瀨名秀明著作。是寄生前夜系列的第一作。','https://zh.wikipedia.org/wiki/%E5%AF%84%E7%94%9F%E5%89%8D%E5%A4%9C_(%E9%81%8A%E6%88%B2)','2026-04-06 22:22:35','2026-04-06 14:11:57','2026-04-06 14:22:35'),(242,'Memories','《MEMORIES》（回忆三部曲）是一部於1995年上映，由大友克洋总監修的日本动画电影。該片以森本晃司的《她的回忆》、岡村天齋的《最臭兵器》、及大友克洋的《大炮之街》三部曲的形式制作。总长110分钟。並在1995年12月23日在日本上映。','https://zh.wikipedia.org/wiki/%E5%9B%9E%E6%86%B6%E4%B8%89%E9%83%A8%E6%9B%B2','2026-04-06 22:22:36','2026-04-06 14:11:57','2026-04-06 14:22:36'),(243,'Melodies','《Miriam\'s Melodies》是香港歌手楊千嬅的第二張新曲加精選專輯，於2003年11月27日推出。該專輯是她離開新藝寶唱片後推出的精選專輯，收錄了她在新藝寶唱片及華星唱片的精選歌曲，亦收錄了2首從未曝光的作品《寒舍》及《舊地》。','https://zh.wikipedia.org/wiki/Miriam\'s_Melodies','2026-04-06 22:22:39','2026-04-06 14:11:57','2026-04-06 14:22:39'),(244,'Durga Devi 陳瑜','佛教和印度教 均發源於古印度，並於公元4世紀左右傳播至東南亞（包括柬埔寨及印度尼西亞），並成為當地主流信仰。佛教於公元前5世紀（於當地所謂的第二次城市化時期 ）在印度河-恆河平原興起，而印度教則被視為吠陀宗教及南亞次大陸上各地本土信仰長期演化、融合後的產物。','https://zh.wikipedia.org/wiki/%E4%BD%9B%E6%95%99%E5%92%8C%E5%8D%B0%E5%BA%A6%E6%95%99','2026-04-06 22:22:41','2026-04-06 14:11:57','2026-04-06 14:22:41'),(245,'Moksha｜瑜伽梵唱單曲《Hanuman on Holiday》 發表會','Moksha｜瑜伽梵唱單曲《Hanuman on Holiday》 發表會 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43'),(246,'森淮Senhuai','简单生活节是由李宗盛、张培仁、馬天宗等人策划发起，自2006年12月开始，每两年一届的生活型態節日活動。集中了音乐舞台、名人分享書房、创意集市等几种策展，以「做喜歡的事，讓喜歡的事有價值」為中心思考出發，除了众多音乐人的表演，还汇聚了各类创作者、农地上的个体耕耘者、服装生活制品的设计人员、意见领袖等等，其目标是“集合台湾最美好的人、事、物”。','https://zh.wikipedia.org/wiki/%E7%B0%A1%E5%96%AE%E7%94%9F%E6%B4%BB%E7%AF%80','2026-04-06 22:22:48','2026-04-06 14:11:57','2026-04-06 14:22:48'),(247,'Chima《 とこしえ 常住》','寺島拓篤 是日本的男性聲優和歌手。石川縣出身，血型為B型，身高166.9cm，星座 射手座，目前隸屬於AXL ONE事務所。','https://zh.wikipedia.org/wiki/%E5%AF%BA%E5%B3%B6%E6%8B%93%E7%AF%A4','2026-04-06 22:22:50','2026-04-06 14:11:57','2026-04-06 14:22:50'),(248,'Despair Boogie—Geronimo Label 2026 台灣巡演 w','Despair Boogie—Geronimo Label 2026 台灣巡演 w 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43'),(249,'tinyteardrop','tinyteardrop 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43'),(250,'2026 CLO’VER','CLO\'VER 是Riser Music於2025年11月24日推出的男子音樂組合。由四位GMMTV演員組成，成員包括蘇維查·皮亞諾普羅（Keen）、廷納西特·伊薩拉蓬彭（Barcode）、奧希里斯·蘇萬納奇普（Aungpao）、皮拉坎·蒂蘇萬（Ashi）。','https://zh.wikipedia.org/wiki/CLO\'VER','2026-04-06 22:23:02','2026-04-06 14:11:57','2026-04-06 14:23:02'),(251,'FELIZZ T-POP SHOWCASE in Taipei','CLO\'VER 是Riser Music於2025年11月24日推出的男子音樂組合。由四位GMMTV演員組成，成員包括蘇維查·皮亞諾普羅（Keen）、廷納西特·伊薩拉蓬彭（Barcode）、奧希里斯·蘇萬納奇普（Aungpao）、皮拉坎·蒂蘇萬（Ashi）。','https://zh.wikipedia.org/wiki/CLO\'VER','2026-04-06 22:23:04','2026-04-06 14:11:57','2026-04-06 14:23:04'),(252,'生活 ê 貓痕－津々','內田真禮，日本女性配音員、演員、歌手。出身於東京都。A型血。I\'m Enterprise所屬。暱稱「まややん」、「まれい」、「まれいたそ」。弟弟內田雄馬與姊姊同樣從事配音。','https://zh.wikipedia.org/wiki/%E5%85%A7%E7%94%B0%E7%9C%9F%E7%A6%AE','2026-04-06 22:23:05','2026-04-06 14:11:57','2026-04-06 14:23:05'),(253,'女王頭','野柳女王頭，或稱女王石，是位於臺灣新北市萬里區野柳風景特定區的蕈狀岩，形似英國伊莉莎白女王頭像，自1962年後成臺灣知名的旅遊景點。','https://zh.wikipedia.org/wiki/%E9%87%8E%E6%9F%B3%E5%A5%B3%E7%8E%8B%E9%A0%AD','2026-04-06 22:23:08','2026-04-06 14:11:57','2026-04-06 14:23:08'),(254,'柏森','刘蒙天（1918年11月—2008年），笔名柏森，男，浙江嵊县人，中国画家，曾任西安美术学院院长、党委书记，研究员，中国美术家协会理事。','https://zh.wikipedia.org/wiki/%E5%88%98%E8%92%99%E5%A4%A9','2026-04-06 22:23:10','2026-04-06 14:11:57','2026-04-06 14:23:10'),(255,'Kuhaku Gokko','Platinum End is a Japanese manga series written by Tsugumi Ohba and illustrated by Takeshi Obata. It was serialized in Shueisha\'s monthly shōnen manga magazine Jump Square from November 2015 to January 2021, with its chapters collected in 14 tankōbon volumes. The series follows Mirai Kakehashi, a student who attempts…','https://en.wikipedia.org/wiki/Platinum_End','2026-04-06 22:23:12','2026-04-06 14:11:57','2026-04-06 14:23:12'),(256,'culenasm','格式塔少女，是一支以全日語歌詞創作的台灣搖滾樂團。','https://zh.wikipedia.org/wiki/%E6%A0%BC%E5%BC%8F%E5%A1%94%E5%B0%91%E5%A5%B3','2026-04-06 22:23:14','2026-04-06 14:11:57','2026-04-06 14:23:14'),(257,'Hakubi – Live in Taipei SPLIT ASIA TOUR 2026','Hakubi – Live in Taipei SPLIT ASIA TOUR 2026 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:57','2026-04-06 14:46:43');
