INSERT INTO `venues` VALUES (1,'高雄流行音樂中心 海音館','未提供','高雄流行音樂中心，為高雄市政府文化局轄下的表演場館暨行政法人，原興建計畫名稱海洋文化及流行音樂中心，基地位於高雄港11-15號碼頭（真愛碼頭、光榮碼頭及苓雅寮車場），占地約11.89公頃，於2021年正式啟用。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E6%B5%81%E8%A1%8C%E9%9F%B3%E6%A8%82%E4%B8%AD%E5%BF%83','2026-04-06 22:23:21','2026-04-06 14:11:56','2026-04-06 14:23:21'),(2,'高雄市音樂館演奏廳','未提供','高雄市音樂館位於高雄市鹽埕區，成立於西元2000年11月，與高雄市立歷史博物館並立於愛河旁。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E9%9F%B3%E6%A8%82%E9%A4%A8','2026-04-06 22:23:24','2026-04-06 14:11:56','2026-04-06 14:23:24'),(3,'台北流行音樂中心表演廳','未提供','臺北流行音樂中心 是臺北市成立的第一個行政法人，位於台灣臺北市南港區的流行音樂園區。園區內包括表演廳、流行音樂文化館、產業區及戶外開放空間。','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8C%97%E6%B5%81%E8%A1%8C%E9%9F%B3%E6%A8%82%E4%B8%AD%E5%BF%83','2026-04-06 22:23:26','2026-04-06 14:11:56','2026-04-06 14:23:26'),(4,'台北國際會議中心大會堂 台北場','台北市信義區信義路五段1','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%9C%83%E8%AD%B0%E4%B8%AD%E5%BF%83','2026-04-06 22:23:28','2026-04-06 14:11:56','2026-04-06 14:23:28'),(5,'高雄市文化中心至德堂','台北市內湖區瑞湖街39號','高雄市文化中心（舊名高雄市立中正文化中心）是位於高雄市苓雅區五福一路的一座大型表演展覽場地，佔地約13甲餘（約12.6公頃），建築形式為有中式建築特徵的粗野主義建築，在國家兩廳院落成啟用前，曾為台灣最大的現代化演藝廳。此文化中心同時也是高雄市政府文化局的辦公地點。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-06 22:23:30','2026-04-06 14:11:56','2026-04-06 14:23:30'),(6,'河岸留言西門紅樓展演館','台北市萬華區西寧南路177號)','西門紅樓，位於臺灣臺北市萬華區西門町，建築由近藤十郎設計，由八角樓與十字樓組成，日治時期原作為西門市場的室內市集；臺灣戰後時期八角樓作為演藝場所，今建物列臺北市定古蹟，作為文創場所與展演空間。','https://zh.wikipedia.org/wiki/%E8%A5%BF%E9%96%80%E7%B4%85%E6%A8%93','2026-04-06 22:23:32','2026-04-06 14:11:56','2026-04-06 14:23:32'),(7,'劍湖山世界主題樂園彩虹劇場','未提供','劍湖山世界 是位於臺灣雲林縣古坑鄉永光村劍湖附近的主題樂園，通稱劍湖山，綜合「休閒、遊樂、文化、科技」四大功能。園區佔地面積60多公頃，主要大型熱門活動常見為痛車，為嘉義耐斯企業旗下之大型遊樂園。和義大世界、六福村、九族文化村並稱臺灣遊樂園的「一三六九」。','https://zh.wikipedia.org/wiki/%E5%8A%8D%E6%B9%96%E5%B1%B1%E4%B8%96%E7%95%8C','2026-04-06 22:23:35','2026-04-06 14:11:56','2026-04-06 14:23:35'),(9,'衛武營國家藝術文化中心表演廳','未提供','衛武營國家藝術文化中心 全銜國家表演藝術中心衛武營國家藝術文化中心。位於臺灣高雄市鳳山區，衛武營都會公園東北側。是臺灣規模最大的文化設施、全球最大單一屋頂綜合劇院，也是南臺灣第一座國家級表演藝術場館，由衛武營藝術文化中心籌備處負責籌備規劃興建，完工後納入國家表演藝術中心，成為該中心轄下場館。','https://zh.wikipedia.org/wiki/%E8%A1%9B%E6%AD%A6%E7%87%9F%E5%9C%8B%E5%AE%B6%E8%97%9D%E8%A1%93%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-06 22:23:37','2026-04-06 14:11:56','2026-04-06 14:23:37'),(10,'高雄市文化中心至德堂','未提供','高雄市文化中心（舊名高雄市立中正文化中心）是位於高雄市苓雅區五福一路的一座大型表演展覽場地，佔地約13甲餘（約12.6公頃），建築形式為有中式建築特徵的粗野主義建築，在國家兩廳院落成啟用前，曾為台灣最大的現代化演藝廳。此文化中心同時也是高雄市政府文化局的辦公地點。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-06 22:23:39','2026-04-06 14:11:56','2026-04-06 14:23:39'),(11,'臺北市政大樓親子劇場','未提供','開拓動漫祭系列活動，是由開拓動漫事業有限公司（杜葳廣告）於臺灣所主辦的同人誌即賣會系列活動之一，分別為兩大系列：開拓動漫祭 及亞洲動漫創作展 ，以臺北市為主要舉辦地點，該公司亦有負責規劃其他活動。官方看板娘為美少女妖精「東華」與美少女人造人「星華」，均由CARNELIAN與ドレン·チェリー（天宮ぽらん）設計。與台灣同人誌販售會（CWT）為臺灣兩大同人誌即賣會體系。','https://zh.wikipedia.org/wiki/%E9%96%8B%E6%8B%93%E5%8B%95%E6%BC%AB%E7%A5%AD','2026-04-06 22:23:41','2026-04-06 14:11:56','2026-04-06 14:23:41'),(12,'台北國際會議中心大會堂','未提供','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%9C%83%E8%AD%B0%E4%B8%AD%E5%BF%83','2026-04-06 22:23:42','2026-04-06 14:11:56','2026-04-06 14:23:42'),(14,'嘉義縣表演藝術中心演藝廳','未提供','嘉義縣表演藝術中心（原稱民雄演藝廳）位於嘉義縣民雄鄉。園區佔地6.6公頃，從1995年起開始規劃，2005年年初完工，於4月22、23日啟用首演雲門舞集《紅樓夢》，5月10日正式營運管理。','https://zh.wikipedia.org/wiki/%E5%98%89%E7%BE%A9%E7%B8%A3%E8%A1%A8%E6%BC%94%E8%97%9D%E8%A1%93%E4%B8%AD%E5%BF%83','2026-04-06 22:23:44','2026-04-06 14:11:56','2026-04-06 14:23:44'),(15,'高雄流行音樂中心 海音館','803高雄市鹽埕區真愛路1號','高雄流行音樂中心，為高雄市政府文化局轄下的表演場館暨行政法人，原興建計畫名稱海洋文化及流行音樂中心，基地位於高雄港11-15號碼頭（真愛碼頭、光榮碼頭及苓雅寮車場），占地約11.89公頃，於2021年正式啟用。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E6%B5%81%E8%A1%8C%E9%9F%B3%E6%A8%82%E4%B8%AD%E5%BF%83','2026-04-06 22:23:46','2026-04-06 14:11:56','2026-04-06 14:23:46'),(16,'高雄市文化中心至善廳','802高雄市苓雅區五福一路67號','高雄市文化中心（舊名高雄市立中正文化中心）是位於高雄市苓雅區五福一路的一座大型表演展覽場地，佔地約13甲餘（約12.6公頃），建築形式為有中式建築特徵的粗野主義建築，在國家兩廳院落成啟用前，曾為台灣最大的現代化演藝廳。此文化中心同時也是高雄市政府文化局的辦公地點。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-06 22:23:47','2026-04-06 14:11:56','2026-04-06 14:23:47'),(17,'台中中興大學惠蓀堂','未提供','費玉清（1955年7月17日—），本名張彦亭，外號小哥，小名亭亭，出身臺灣臺北，臺灣男歌手、主持人，以其華語、臺語流行歌曲演唱及綜藝節目主持表現等，在當代華語世界廣為人知。他在2019年舉行告別演出，後於2020年初完成合約工作後宣布自演藝事業退休。他是前歌手費貞綾及藝人張菲的弟弟。','https://zh.wikipedia.org/wiki/%E8%B2%BB%E7%8E%89%E6%B8%85','2026-04-06 22:23:49','2026-04-06 14:11:56','2026-04-06 14:23:49'),(19,'台北國際會議中心大會堂','台北市信義區信義路五段1號)','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%9C%83%E8%AD%B0%E4%B8%AD%E5%BF%83','2026-04-06 22:23:51','2026-04-06 14:11:56','2026-04-06 14:23:51'),(20,'臺南文化中心演藝廳 臺南場','台北市士林區文林路751號)','臺南文化中心是臺南市政府文化局永華文化中心管理科所轄之藝文場館，位於臺南市東區，鄰近巴克禮紀念公園與台糖長榮酒店，昔日為竹溪流經之地。此處經常舉行各種藝文活動，是臺南市民的休閒去處之一。開放時間為週三到週日09:00~17:00，週一週二休館。此外，該文化中心是臺灣各縣市唯一獲得建築金牌獎的文化中心，也是最早建立義務服務人員自治制度與推展家庭日服務的文化中心。與新營文化中心並列臺南兩大文化中心。','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8D%97%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-06 22:23:53','2026-04-06 14:11:56','2026-04-06 14:23:53'),(21,'嘉義縣表演藝術中心演藝廳','屏東縣屏東市和平路427號','嘉義縣表演藝術中心（原稱民雄演藝廳）位於嘉義縣民雄鄉。園區佔地6.6公頃，從1995年起開始規劃，2005年年初完工，於4月22、23日啟用首演雲門舞集《紅樓夢》，5月10日正式營運管理。','https://zh.wikipedia.org/wiki/%E5%98%89%E7%BE%A9%E7%B8%A3%E8%A1%A8%E6%BC%94%E8%97%9D%E8%A1%93%E4%B8%AD%E5%BF%83','2026-04-06 22:23:55','2026-04-06 14:11:56','2026-04-06 14:23:55'),(23,'Legacy Taipei 音樂展演空間','台北市八德路一段1號 台北華山創意園區 中五館','詹雯婷（1981年8月27日—），臺灣創作女歌手。出道時以飛（或者稱飛兒）之藝名，擔任飛兒樂團主唱。2004年以經典電視劇《鬥魚》片尾曲〈Lydia〉知名，隔年獲第16屆金曲獎最佳新人獎。2018年10月詹雯婷宣布加盟亞神音樂，以本名繼續演藝活動。','https://zh.wikipedia.org/wiki/%E8%A9%B9%E9%9B%AF%E5%A9%B7','2026-04-06 22:23:57','2026-04-06 14:11:56','2026-04-06 14:23:57'),(24,'音浪塔四樓常設展','未提供','江西省美术馆，馆址初名毛泽东思想胜利万岁馆，俗称万岁馆，位于中国江西省南昌市八一广场西侧，是一家集展览、收藏、研究、教育等功能的公益性美术馆。','https://zh.wikipedia.org/wiki/%E6%B1%9F%E8%A5%BF%E7%9C%81%E7%BE%8E%E6%9C%AF%E9%A6%86','2026-04-06 22:23:59','2026-04-06 14:11:56','2026-04-06 14:23:59'),(25,'迴響音樂展演空間','未提供','TFAP來自台灣的台北，2019年成立，是以貝斯、鼓、吉他為主要編制的後搖滾樂團，於2020年10月發行首張EP《The Fog Talks to Me》。是第一屆以後搖滾為主的「秋波音樂節」的主要推手。','https://zh.wikipedia.org/wiki/TFAP','2026-04-06 22:24:01','2026-04-06 14:11:56','2026-04-06 14:24:01'),(26,'Revolver','未提供','《左轮手枪》 是英國搖滾樂團披头士的第七張录音室專輯，音樂製作人乔治·马丁。該專輯由EMI旗下Parlophone唱片於1966年8月5日在英国发行，三天之後於美國发行。這張專輯標誌著樂團從1965年的《Rubber Soul》專輯更進一步，更專注於录音室音樂的創新與製作，一年後於《比伯軍曹寂寞芳心俱樂部》專輯達到頂峰。','https://zh.wikipedia.org/wiki/%E5%B7%A6%E8%BD%AE%E6%89%8B%E6%9E%AA_(%E6%8A%AB%E5%A4%B4%E5%A3%AB%E4%B8%93%E8%BE%91)','2026-04-06 22:24:06','2026-04-06 14:11:56','2026-04-06 14:24:06'),(27,'The Wall Livehouse (臺北市文山區羅斯福路四段 200 號','臺北市文山區羅斯福路四段','The Wall Livehouse (臺北市文山區羅斯福路四段 200 號 為本資料庫收錄之演出場地，地址為 臺北市文山區羅斯福路四段，近期收錄活動 1 場。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(28,'LIVE WAREHOUSE 小庫','高雄市鹽埕區大義街 2-5 號C10 倉庫','芒果醬 是台灣一個男子樂團。','https://zh.wikipedia.org/wiki/%E8%8A%92%E6%9E%9C%E9%86%AC','2026-04-06 22:24:14','2026-04-06 14:11:56','2026-04-06 14:24:14'),(29,'野地方 Wildlab','未提供','野地方 Wildlab 為本資料庫收錄之演出場地，近期收錄活動 3 場。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(30,'@soundlivehouse','未提供','@soundlivehouse 為本資料庫收錄之演出場地，近期收錄活動 1 場。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(31,'Revolver (台北市中正區羅斯福路一段1-2號) 時間：19:30 入場 / 20:00 開演','台北市中正區羅斯福路一段1-2號)','Revolver (台北市中正區羅斯福路一段1-2號) 時間：19:30 入場 / 20:00 開演 為本資料庫收錄之演出場地，地址為 台北市中正區羅斯福路一段1-2號)，近期收錄活動 1 場。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(33,'SUB','台北市南港區市民大道八段99號 / 入口位於臺北流行音樂中心南基地戶外廣場','D-sub 是常見的电子连接器，因其接頭處D型的金屬屏蔽層而得名，以往常用於電腦的电子连接器上。在剛開始發展使用D-sub時，D-sub是電腦系統中最小型的連接器之一，所以稱作D-subminiature。','https://zh.wikipedia.org/wiki/D-sub','2026-04-06 22:24:37','2026-04-06 14:11:56','2026-04-06 14:24:37'),(34,'迴響音樂展演空間 SOUND Live House','未提供','live house 為和製英語，指以現場演奏為主的小型音樂表演場所。該詞主要在東亞地區使用。有的live house會同時經營酒吧或提供其他夜生活娛樂，因此某些設有舞臺或舞池的餐廳或咖啡廳也有可能被稱為live house。live house主要演出搖滾、爵士、民謠等音樂風格。','https://zh.wikipedia.org/wiki/Live_house','2026-04-06 22:24:39','2026-04-06 14:11:56','2026-04-06 14:24:39'),(35,'Legacy Taichung 音樂展演空間','台中市西屯區安和路117號','詹雯婷（1981年8月27日—），臺灣創作女歌手。出道時以飛（或者稱飛兒）之藝名，擔任飛兒樂團主唱。2004年以經典電視劇《鬥魚》片尾曲〈Lydia〉知名，隔年獲第16屆金曲獎最佳新人獎。2018年10月詹雯婷宣布加盟亞神音樂，以本名繼續演藝活動。','https://zh.wikipedia.org/wiki/%E8%A9%B9%E9%9B%AF%E5%A9%B7','2026-04-06 22:24:41','2026-04-06 14:11:56','2026-04-06 14:24:41'),(37,'LIVE WAREHOUSE','高雄市鹽埕區大義街 2-5 號C10 倉庫','高雄流行音樂中心，為高雄市政府文化局轄下的表演場館暨行政法人，原興建計畫名稱海洋文化及流行音樂中心，基地位於高雄港11-15號碼頭（真愛碼頭、光榮碼頭及苓雅寮車場），占地約11.89公頃，於2021年正式啟用。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E6%B5%81%E8%A1%8C%E9%9F%B3%E6%A8%82%E4%B8%AD%E5%BF%83','2026-04-06 22:24:43','2026-04-06 14:11:56','2026-04-06 14:24:43'),(38,'Seety新城視 展演空間 🐶 台中站 演出日期｜2026.04.26（日）19:30','未提供','Seety新城視 展演空間 🐶 台中站 演出日期｜2026.04.26（日）19:30 為本資料庫收錄之演出場地，近期收錄活動 1 場。',NULL,'2026-04-06 22:46:43','2026-04-06 14:11:56','2026-04-06 14:46:43'),(39,'SOUND Live House','未提供','live house 為和製英語，指以現場演奏為主的小型音樂表演場所。該詞主要在東亞地區使用。有的live house會同時經營酒吧或提供其他夜生活娛樂，因此某些設有舞臺或舞池的餐廳或咖啡廳也有可能被稱為live house。live house主要演出搖滾、爵士、民謠等音樂風格。','https://zh.wikipedia.org/wiki/Live_house','2026-04-06 22:24:52','2026-04-06 14:11:56','2026-04-06 14:24:52'),(40,'台北小巨蛋（TAIPEI ARENA）','未提供','臺北小巨蛋 是位於臺灣臺北市松山區中崙的多功能體育館，屬於競技場級場館，坐落於南京東路及敦化北路交叉口。除了提供體育競賽場地之外，亦經常舉辦演唱會、頒獎典禮等大型文藝活動，為臺灣娛樂業界的指標場所之一。面對南京東路的正門設有巨型LED電子看板「臺北天幕」（或稱小巨蛋天幕），平時播送廣告與活動訊息，亦為藝文活動舞台。另主場館旁附設一座溜冰館（小巨蛋冰上樂園）。場館東側設有同名捷運車站。目前臺北小巨蛋主場館及溜冰館均由臺北捷運公司轄下之北捷遊憩事業股份有限公司 營運。','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8C%97%E5%B0%8F%E5%B7%A8%E8%9B%8B','2026-04-06 22:24:54','2026-04-06 14:11:56','2026-04-06 14:24:54'),(42,'高雄國家體育場 (世運主場館)','未提供','高雄國家體育場，原稱2009世運會主場館（簡稱世運主場館），別稱龍騰體育場，是位於臺灣高雄市左營區的多用途體育場，位於左營區世運大道（原中海路）和軍校路口，原為海軍陸戰隊勝利營區。其為行政院體育委員會（現運動部）因應爭取主辦國際綜合運動賽會及舉辦2009年世界運動會而籌建，委託高雄市政府工務局新建工程處辦理興建事宜，乃目前臺灣最大的體育場館。','https://zh.wikipedia.org/wiki/%E5%9C%8B%E5%AE%B6%E9%AB%94%E8%82%B2%E5%A0%B4_(%E9%AB%98%E9%9B%84%E5%B8%82)','2026-04-06 22:24:56','2026-04-06 14:11:56','2026-04-06 14:24:56'),(43,'高雄國家體育場 (世運主場館) Kaohsiung National Stadium','未提供','高雄國家體育場，原稱2009世運會主場館（簡稱世運主場館），別稱龍騰體育場，是位於臺灣高雄市左營區的多用途體育場，位於左營區世運大道（原中海路）和軍校路口，原為海軍陸戰隊勝利營區。其為行政院體育委員會（現運動部）因應爭取主辦國際綜合運動賽會及舉辦2009年世界運動會而籌建，委託高雄市政府工務局新建工程處辦理興建事宜，乃目前臺灣最大的體育場館。','https://zh.wikipedia.org/wiki/%E5%9C%8B%E5%AE%B6%E9%AB%94%E8%82%B2%E5%A0%B4_(%E9%AB%98%E9%9B%84%E5%B8%82)','2026-04-06 22:24:58','2026-04-06 14:11:56','2026-04-06 14:24:58'),(44,'台北小巨蛋 (Taipei Arena)','未提供','臺北小巨蛋 是位於臺灣臺北市松山區中崙的多功能體育館，屬於競技場級場館，坐落於南京東路及敦化北路交叉口。除了提供體育競賽場地之外，亦經常舉辦演唱會、頒獎典禮等大型文藝活動，為臺灣娛樂業界的指標場所之一。面對南京東路的正門設有巨型LED電子看板「臺北天幕」（或稱小巨蛋天幕），平時播送廣告與活動訊息，亦為藝文活動舞台。另主場館旁附設一座溜冰館（小巨蛋冰上樂園）。場館東側設有同名捷運車站。目前臺北小巨蛋主場館及溜冰館均由臺北捷運公司轄下之北捷遊憩事業股份有限公司 營運。','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8C%97%E5%B0%8F%E5%B7%A8%E8%9B%8B','2026-04-06 22:24:59','2026-04-06 14:11:56','2026-04-06 14:24:59'),(45,'台北國際會議中心(TICC)','未提供','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%9C%83%E8%AD%B0%E4%B8%AD%E5%BF%83','2026-04-06 22:25:01','2026-04-06 14:11:56','2026-04-06 14:25:01'),(46,'TAIPEI INTERNATIONAL CONVENTION CENTER (TICC)','未提供','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%