DROP TABLE IF EXISTS `活動`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `活動` (
  `event_id_pk` bigint unsigned NOT NULL AUTO_INCREMENT,
  `venue_id_fk` bigint unsigned DEFAULT NULL,
  `artist_id_fk` bigint unsigned DEFAULT NULL,
  `活動名稱` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `票價` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `票種` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `活動時間` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `售票時間` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `活動連結` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`event_id_pk`),
  UNIQUE KEY `uk_event_dedupe` (`活動名稱`(255),`活動時間`(120),`venue_id_fk`,`artist_id_fk`,`活動連結`(255)),
  KEY `fk_event_venue` (`venue_id_fk`),
  KEY `fk_event_artist` (`artist_id_fk`),
  CONSTRAINT `fk_event_artist` FOREIGN KEY (`artist_id_fk`) REFERENCES `藝人` (`artist_id_pk`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_event_venue` FOREIGN KEY (`venue_id_fk`) REFERENCES `活動地點` (`venue_id_pk`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=348 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

