/*!50013 DEFINER=`root`@`127.0.0.1` SQL SECURITY DEFINER */
/*!50001 VIEW `活動聯合檢視` AS select `a`.`event_id_pk` AS `event_id_pk`,`a`.`活動名稱` AS `活動名稱`,`r`.`artist_id_pk` AS `artist_id_pk`,`r`.`藝人名稱` AS `藝人名稱`,`v`.`venue_id_pk` AS `venue_id_pk`,`v`.`場地名稱` AS `場地名稱`,`v`.`地址` AS `地址`,`p`.`platform_id_pk` AS `platform_id_pk`,`p`.`平台名稱` AS `平台名稱`,`a`.`票價` AS `票價`,`a`.`票種` AS `票種`,`a`.`活動時間` AS `活動時間`,`a`.`售票時間` AS `售票時間`,`a`.`活動連結` AS `活動連結` from (((`活動` `a` left join `藝人` `r` on((`a`.`artist_id_fk` = `r`.`artist_id_pk`))) left join `活動地點` `v` on((`a`.`venue_id_fk` = `v`.`venue_id_pk`))) left join `售票平台` `p` on((`p`.`event_id_fk` = `a`.`event_id_pk`))) */;
